//! Display width computation (per-character, control characters count as zero).

use crate::width_table::WIDTH_TABLE;

pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if cp < 0x20 {
        return 0;
    }
    if cp < 0x7F {
        return 1;
    }
    if cp < 0xA0 {
        return 0;
    }
    // binary search
    let mut lo = 0usize;
    let mut hi = WIDTH_TABLE.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (s, e, w) = WIDTH_TABLE[mid];
        if cp < s {
            hi = mid;
        } else if cp > e {
            lo = mid + 1;
        } else {
            return w as usize;
        }
    }
    1
}

/// Returns `None` for control characters (like the classic unicode-width API).
pub fn char_width_opt(c: char) -> Option<usize> {
    let cp = c as u32;
    if cp == 0 {
        return Some(0);
    }
    if cp < 0x20 || (0x7F..0xA0).contains(&cp) {
        return None;
    }
    Some(char_width(c))
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

/// Width of a string ignoring ANSI escape sequences of the form ESC [ ... m.
pub fn display_width(text: &str) -> usize {
    #[derive(PartialEq, Clone, Copy)]
    enum State {
        Normal,
        EscapeChar,
        OpenBracket,
        AfterEscape,
    }
    let width = str_width(text);
    let mut state = State::Normal;
    let mut hidden = 0usize;
    for c in text.chars() {
        state = match (state, c) {
            (State::Normal, '\u{1b}') => State::EscapeChar,
            (State::EscapeChar, '[') => State::OpenBracket,
            (State::EscapeChar, _) => State::Normal,
            (State::OpenBracket, 'm') => State::AfterEscape,
            _ => state,
        };
        if state == State::OpenBracket || state == State::AfterEscape {
            if char_width(c) > 0 {
                hidden += 1;
            }
        }
        if state == State::AfterEscape {
            state = State::Normal;
        }
    }
    width.saturating_sub(hidden)
}
