//! Minimal port of the classic greedy text wrapping algorithm (hyphen aware,
//! no word breaking), used for help messages.

use crate::width::{char_width_opt, str_width};

fn is_ws(c: char) -> bool {
    c.is_whitespace() && c != '\u{A0}'
}

fn hyphen_split(word: &str) -> Vec<(usize, &str)> {
    // returns list of (head_len_bytes, head) candidates, smallest first, whole word last
    let mut out = Vec::new();
    let chars: Vec<(usize, char)> = word.char_indices().collect();
    if chars.len() < 2 {
        out.push((word.len(), word));
        return out;
    }
    let mut prev = chars[0].1;
    let mut idx = chars[1].0;
    let mut cur = chars[1].1;
    for &(i, next) in chars.iter().skip(2) {
        if prev.is_alphanumeric() && cur == '-' && next.is_alphanumeric() {
            let head = &word[..idx + 1];
            out.push((head.len(), head));
        }
        prev = cur;
        idx = i;
        cur = next;
    }
    out.push((word.len(), word));
    out
}

pub fn wrap_line(source: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut start = 0usize;
    let mut split = 0usize;
    let mut split_len = 0usize;
    let mut line_width = 0usize;
    let mut line_width_at_split = 0usize;
    let mut in_whitespace = false;
    let chars: Vec<(usize, char)> = source.char_indices().collect();
    let mut k = 0;
    while k < chars.len() {
        let (idx, ch) = chars[k];
        k += 1;
        if ch == '\u{1b}' && k < chars.len() && chars[k].1 == '[' {
            k += 1;
            while k < chars.len() {
                let c = chars[k].1;
                k += 1;
                if ('\u{40}'..='\u{7e}').contains(&c) {
                    break;
                }
            }
            continue;
        }
        let char_width = char_width_opt(ch).unwrap_or(0);
        let char_len = ch.len_utf8();
        if ch == '\n' {
            split = idx;
            split_len = char_len;
            line_width_at_split = line_width;
            in_whitespace = false;
            if split + split_len < source.len() {
                lines.push(source[start..split].to_string());
                start = split + split_len;
                line_width = 0;
                continue;
            }
        } else if is_ws(ch) {
            if in_whitespace {
                split_len += char_len;
            } else {
                split = idx;
                split_len = char_len;
            }
            line_width_at_split = line_width + char_width;
            in_whitespace = true;
        } else if line_width + char_width > width {
            in_whitespace = false;
            let remaining = &source[split + split_len..];
            let final_word = match remaining.find(is_ws) {
                Some(i) => &remaining[..i],
                None => remaining,
            };
            let splits = hyphen_split(final_word);
            for &(hlen, head) in splits.iter().rev() {
                if line_width_at_split + str_width(head) <= width {
                    split += split_len + hlen;
                    split_len = 0;
                    break;
                }
            }
            if start >= split {
                split = start + splits[0].0;
                split_len = 0;
                line_width_at_split = line_width;
            }
            if start < split {
                lines.push(source[start..split].to_string());
                start = split + split_len;
                line_width -= line_width_at_split;
                line_width += char_width;
                continue;
            }
        } else {
            in_whitespace = false;
        }
        line_width += char_width;
    }
    if start < source.len() {
        lines.push(source[start..].to_string());
    }
    lines
}

/// `fill` each line of `help` separately, joined by newlines.
pub fn wrap_help(help: &str, avail: usize) -> String {
    help.lines()
        .map(|l| wrap_line(l, avail).join("\n"))
        .collect::<Vec<_>>()
        .join("\n")
}
EOF
