//! A TOML parser and deserializer mimicking the behaviour (including error
//! messages) of the classic `toml` 0.5 crate as used by pier.

use std::collections::VecDeque;

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

#[derive(Debug, Clone, PartialEq)]
enum Token<'a> {
    Whitespace(&'a str),
    Newline,
    Comment(&'a str),
    Equals,
    Period,
    Comma,
    Colon,
    Plus,
    LeftBrace,
    RightBrace,
    LeftBracket,
    RightBracket,
    Keylike(&'a str),
    Str {
        src: &'a str,
        val: String,
        multiline: bool,
    },
}

impl<'a> Token<'a> {
    fn describe(&self) -> &'static str {
        match self {
            Token::Keylike(_) => "an identifier",
            Token::Equals => "an equals",
            Token::Period => "a period",
            Token::Comment(_) => "a comment",
            Token::Newline => "a newline",
            Token::Whitespace(_) => "whitespace",
            Token::Comma => "a comma",
            Token::RightBrace => "a right brace",
            Token::LeftBrace => "a left brace",
            Token::RightBracket => "a right bracket",
            Token::LeftBracket => "a left bracket",
            Token::Str { multiline, .. } => {
                if *multiline {
                    "a multiline string"
                } else {
                    "a string"
                }
            }
            Token::Colon => "a colon",
            Token::Plus => "a plus",
        }
    }
}

#[derive(Debug, Clone)]
enum TokenError {
    InvalidCharInString(usize, char),
    InvalidEscape(usize, char),
    InvalidHexEscape(usize, char),
    InvalidEscapeValue(usize, u32),
    NewlineInString(usize),
    Unexpected(usize, char),
    UnterminatedString(usize),
    NewlineInTableKey(usize),
    MultilineStringKey(usize),
    EmptyTableKey(usize),
    Wanted {
        at: usize,
        expected: &'static str,
        found: &'static str,
    },
}

#[derive(Clone, Copy)]
struct Tokenizer<'a> {
    input: &'a str,
    pos: usize,
}

fn is_keylike(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || ch == '-' || ch == '_'
}

impl<'a> Tokenizer<'a> {
    fn new(input: &'a str) -> Tokenizer<'a> {
        let mut t = Tokenizer { input, pos: 0 };
        t.eatc('\u{feff}');
        t
    }

    fn one(&mut self) -> Option<(usize, char)> {
        let c = self.input[self.pos..].chars().next()?;
        let i = self.pos;
        self.pos += c.len_utf8();
        if c == '\r' && self.input[self.pos..].starts_with('\n') {
            self.pos += 1;
            return Some((i, '\n'));
        }
        Some((i, c))
    }

    fn peek_one(&self) -> Option<(usize, char)> {
        let mut c = *self;
        c.one()
    }

    fn eatc(&mut self, ch: char) -> bool {
        match self.peek_one() {
            Some((_, c)) if c == ch => {
                self.one();
                true
            }
            _ => false,
        }
    }

    fn current(&self) -> usize {
        self.pos
    }

    fn step_span(&self, start: usize) -> Span {
        let end = self.peek_one().map(|t| t.0).unwrap_or(self.input.len());
        Span { start, end }
    }

    fn next(&mut self) -> Result<Option<(Span, Token<'a>)>, TokenError> {
        let (start, token) = match self.one() {
            Some((start, '\n')) => (start, Token::Newline),
            Some((start, ' ')) | Some((start, '\t')) => (start, self.whitespace_token(start)),
            Some((start, '#')) => (start, self.comment_token(start)),
            Some((start, '=')) => (start, Token::Equals),
            Some((start, '.')) => (start, Token::Period),
            Some((start, ',')) => (start, Token::Comma),
            Some((start, ':')) => (start, Token::Colon),
            Some((start, '+')) => (start, Token::Plus),
            Some((start, '{')) => (start, Token::LeftBrace),
            Some((start, '}')) => (start, Token::RightBrace),
            Some((start, '[')) => (start, Token::LeftBracket),
            Some((start, ']')) => (start, Token::RightBracket),
            Some((start, '\'')) => {
                let t = self.read_string('\'', start)?;
                return Ok(Some((self.step_span(start), t)));
            }
            Some((start, '"')) => {
                let t = self.read_string('"', start)?;
                return Ok(Some((self.step_span(start), t)));
            }
            Some((start, ch)) if is_keylike(ch) => (start, self.keylike(start)),
            Some((start, ch)) => return Err(TokenError::Unexpected(start, ch)),
            None => return Ok(None),
        };
        let span = self.step_span(start);
        Ok(Some((span, token)))
    }

    fn peek(&self) -> Result<Option<(Span, Token<'a>)>, TokenError> {
        let mut c = *self;
        c.next()
    }

    fn eat(&mut self, expected: Token<'a>) -> Result<bool, TokenError> {
        self.eat_spanned(expected).map(|s| s.is_some())
    }

    fn eat_spanned(&mut self, expected: Token<'a>) -> Result<Option<Span>, TokenError> {
        let span = match self.peek()? {
            Some((span, ref found)) if expected == *found => span,
            _ => return Ok(None),
        };
        let _ = self.next();
        Ok(Some(span))
    }

    fn expect(&mut self, expected: Token<'a>) -> Result<(), TokenError> {
        self.expect_spanned(expected).map(|_| ())
    }

    fn expect_spanned(&mut self, expected: Token<'a>) -> Result<Span, TokenError> {
        let current = self.current();
        match self.next()? {
            Some((span, found)) => {
                if expected == found {
                    Ok(span)
                } else {
                    Err(TokenError::Wanted {
                        at: current,
                        expected: expected.describe(),
                        found: found.describe(),
                    })
                }
            }
            None => Err(TokenError::Wanted {
                at: self.input.len(),
                expected: expected.describe(),
                found: "eof",
            }),
        }
    }

    fn table_key(&mut self) -> Result<(Span, String), TokenError> {
        let current = self.current();
        match self.next()? {
            Some((span, Token::Keylike(k))) => Ok((span, k.to_string())),
            Some((span, Token::Str { src, val, multiline })) => {
                let offset = src.as_ptr() as usize - self.input.as_ptr() as usize;
                if multiline {
                    return Err(TokenError::MultilineStringKey(offset));
                }
                if val.is_empty() {
                    return Err(TokenError::EmptyTableKey(offset));
                }
                match src.find('\n') {
                    None => Ok((span, val)),
                    Some(i) => Err(TokenError::NewlineInTableKey(offset + i)),
                }
            }
            Some((_, other)) => Err(TokenError::Wanted {
                at: current,
                expected: "a table key",
                found: other.describe(),
            }),
            None => Err(TokenError::Wanted {
                at: self.input.len(),
                expected: "a table key",
                found: "eof",
            }),
        }
    }

    fn eat_whitespace(&mut self) {
        while self.eatc(' ') || self.eatc('\t') {}
    }

    fn eat_comment(&mut self) -> Result<bool, TokenError> {
        if !self.eatc('#') {
            return Ok(false);
        }
        let _ = self.comment_token(0);
        self.eat_newline_or_eof().map(|()| true)
    }

    fn eat_newline_or_eof(&mut self) -> Result<(), TokenError> {
        let current = self.current();
        match self.next()? {
            None | Some((_, Token::Newline)) => Ok(()),
            Some((_, other)) => Err(TokenError::Wanted {
                at: current,
                expected: "newline",
                found: other.describe(),
            }),
        }
    }

    fn skip_to_newline(&mut self) {
        loop {
            match self.one() {
                Some((_, '\n')) | None => break,
                _ => {}
            }
        }
    }

    fn whitespace_token(&mut self, start: usize) -> Token<'a> {
        while self.eatc(' ') || self.eatc('\t') {}
        Token::Whitespace(&self.input[start..self.current()])
    }

    fn comment_token(&mut self, start: usize) -> Token<'a> {
        while let Some((_, ch)) = self.peek_one() {
            if ch != '\t' && (ch < '\u{20}' || ch > '\u{10ffff}') {
                break;
            }
            self.one();
        }
        Token::Comment(&self.input[start..self.current()])
    }

    fn keylike(&mut self, start: usize) -> Token<'a> {
        while let Some((_, ch)) = self.peek_one() {
            if !is_keylike(ch) {
                break;
            }
            self.one();
        }
        Token::Keylike(&self.input[start..self.current()])
    }

    fn read_string(&mut self, delim: char, start: usize) -> Result<Token<'a>, TokenError> {
        let mut multiline = false;
        if self.eatc(delim) {
            if self.eatc(delim) {
                multiline = true;
            } else {
                return Ok(Token::Str {
                    src: &self.input[start..start + 2],
                    val: String::new(),
                    multiline: false,
                });
            }
        }
        let mut val = String::new();
        let mut n = 0;
        loop {
            n += 1;
            match self.one() {
                Some((i, '\n')) => {
                    if multiline {
                        if n == 1 {
                            val.clear();
                        } else {
                            val.push('\n');
                        }
                        continue;
                    } else {
                        return Err(TokenError::NewlineInString(i));
                    }
                }
                Some((_, ch)) if ch == delim => {
                    if multiline {
                        if !self.eatc(delim) {
                            val.push(delim);
                            continue;
                        }
                        if !self.eatc(delim) {
                            val.push(delim);
                            val.push(delim);
                            continue;
                        }
                    }
                    return Ok(Token::Str {
                        src: &self.input[start..self.current()],
                        val,
                        multiline,
                    });
                }
                Some((i, c)) => {
                    if delim == '\'' {
                        if c == '\u{09}' || ('\u{20}' <= c && c != '\u{7f}') {
                            val.push(c);
                        } else {
                            return Err(TokenError::InvalidCharInString(i, c));
                        }
                    } else {
                        self.basic_char(&mut val, multiline, i, c, start)?;
                    }
                }
                None => return Err(TokenError::UnterminatedString(start)),
            }
        }
    }

    fn basic_char(
        &mut self,
        val: &mut String,
        multi: bool,
        i: usize,
        ch: char,
        start: usize,
    ) -> Result<(), TokenError> {
        match ch {
            '\\' => {
                match self.one() {
                    Some((_, '"')) => val.push('"'),
                    Some((_, '\\')) => val.push('\\'),
                    Some((_, 'b')) => val.push('\u{8}'),
                    Some((_, 'f')) => val.push('\u{c}'),
                    Some((_, 'n')) => val.push('\n'),
                    Some((_, 'r')) => val.push('\r'),
                    Some((_, 't')) => val.push('\t'),
                    Some((i, c @ 'u')) | Some((i, c @ 'U')) => {
                        let len = if c == 'u' { 4 } else { 8 };
                        val.push(self.hex(start, i, len)?);
                    }
                    Some((i, c)) if multi && (c == ' ' || c == '\t' || c == '\n') => {
                        if c != '\n' {
                            while let Some((_, ch)) = self.peek_one() {
                                match ch {
                                    ' ' | '\t' => {
                                        self.one();
                                        continue;
                                    }
                                    '\n' => {
                                        self.one();
                                        break;
                                    }
                                    _ => return Err(TokenError::InvalidEscape(i, c)),
                                }
                            }
                        }
                        while let Some((_, ch)) = self.peek_one() {
                            match ch {
                                ' ' | '\t' | '\n' => {
                                    self.one();
                                }
                                _ => break,
                            }
                        }
                    }
                    Some((i, c)) => return Err(TokenError::InvalidEscape(i, c)),
                    None => return Err(TokenError::UnterminatedString(start)),
                }
                Ok(())
            }
            ch if ch == '\u{09}' || ('\u{20}' <= ch && ch != '\u{7f}') => {
                val.push(ch);
                Ok(())
            }
            _ => Err(TokenError::InvalidCharInString(i, ch)),
        }
    }

    fn hex(&mut self, start: usize, i: usize, len: usize) -> Result<char, TokenError> {
        let mut buf = String::with_capacity(len);
        for _ in 0..len {
            match self.one() {
                Some((_, ch)) if (ch as u32) <= 0x7F && ch.is_ascii_hexdigit() => buf.push(ch),
                Some((i, ch)) => return Err(TokenError::InvalidHexEscape(i, ch)),
                None => return Err(TokenError::UnterminatedString(start)),
            }
        }
        let val = u32::from_str_radix(&buf, 16).unwrap();
        match char::from_u32(val) {
            Some(ch) => Ok(ch),
            None => Err(TokenError::InvalidEscapeValue(i, val)),
        }
    }
}

// ---------------------------------------------------------------------------
// Errors

#[derive(Debug, Clone)]
pub struct DeError {
    msg: String,
    keys: Vec<String>,
    line: Option<usize>,
}

impl DeError {
    pub fn custom(msg: String) -> DeError {
        DeError {
            msg,
            keys: Vec::new(),
            line: None,
        }
    }
    fn add_key_context(&mut self, key: &str) {
        self.keys.insert(0, key.to_string());
    }
}

impl std::fmt::Display for DeError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.msg)?;
        if !self.keys.is_empty() {
            write!(f, " for key `{}`", self.keys.join("."))?;
        }
        if let Some(line) = self.line {
            write!(f, " at line {}", line + 1)?;
        }
        Ok(())
    }
}

fn escape_default_char(c: char) -> String {
    c.escape_default().collect()
}

enum ErrorKind {
    UnexpectedEof,
    InvalidCharInString(char),
    InvalidEscape(char),
    InvalidHexEscape(char),
    InvalidEscapeValue(u32),
    NewlineInString,
    Unexpected(char),
    UnterminatedString,
    NewlineInTableKey,
    NumberInvalid,
    DateInvalid,
    MixedArrayType,
    DuplicateTable(String),
    RedefineAsArray,
    EmptyTableKey,
    MultilineStringKey,
    Wanted {
        expected: &'static str,
        found: &'static str,
    },
    DottedKeyInvalidType,
}

impl ErrorKind {
    fn message(&self) -> String {
        match self {
            ErrorKind::UnexpectedEof => "unexpected eof encountered".to_string(),
            ErrorKind::InvalidCharInString(c) => {
                format!("invalid character in string: `{}`", escape_default_char(*c))
            }
            ErrorKind::InvalidEscape(c) => format!(
                "invalid escape character in string: `{}`",
                escape_default_char(*c)
            ),
            ErrorKind::InvalidHexEscape(c) => format!(
                "invalid hex escape character in string: `{}`",
                escape_default_char(*c)
            ),
            ErrorKind::InvalidEscapeValue(v) => format!("invalid escape value: `{}`", v),
            ErrorKind::NewlineInString => "newline in string found".to_string(),
            ErrorKind::Unexpected(c) => {
                format!("unexpected character found: `{}`", escape_default_char(*c))
            }
            ErrorKind::UnterminatedString => "unterminated string".to_string(),
            ErrorKind::NewlineInTableKey => "found newline in table key".to_string(),
            ErrorKind::NumberInvalid => "invalid number".to_string(),
            ErrorKind::DateInvalid => "invalid date".to_string(),
            ErrorKind::MixedArrayType => "mixed types in an array".to_string(),
            ErrorKind::DuplicateTable(s) => format!("redefinition of table `{}`", s),
            ErrorKind::RedefineAsArray => "table redefined as array".to_string(),
            ErrorKind::EmptyTableKey => "empty table key found".to_string(),
            ErrorKind::MultilineStringKey => {
                "multiline strings are not allowed for key".to_string()
            }
            ErrorKind::Wanted { expected, found } => format!("expected {}, found {}", expected, found),
            ErrorKind::DottedKeyInvalidType => {
                "dotted key attempted to extend non-table type".to_string()
            }
        }
    }
}

fn to_line(input: &str, offset: usize) -> usize {
    let mut cur = 0;
    for (i, line) in input.lines().enumerate() {
        if cur + line.len() + 1 > offset {
            return i;
        }
        cur += line.len() + 1;
    }
    input.lines().count()
}

fn make_error(input: &str, at: usize, kind: ErrorKind) -> DeError {
    DeError {
        msg: kind.message(),
        keys: Vec::new(),
        line: Some(to_line(input, at)),
    }
}

fn token_error(input: &str, e: TokenError) -> DeError {
    match e {
        TokenError::InvalidCharInString(at, ch) => make_error(input, at, ErrorKind::InvalidCharInString(ch)),
        TokenError::InvalidEscape(at, ch) => make_error(input, at, ErrorKind::InvalidEscape(ch)),
        TokenError::InvalidEscapeValue(at, v) => make_error(input, at, ErrorKind::InvalidEscapeValue(v)),
        TokenError::InvalidHexEscape(at, ch) => make_error(input, at, ErrorKind::InvalidHexEscape(ch)),
        TokenError::NewlineInString(at) => make_error(input, at, ErrorKind::NewlineInString),
        TokenError::Unexpected(at, ch) => make_error(input, at, ErrorKind::Unexpected(ch)),
        TokenError::UnterminatedString(at) => make_error(input, at, ErrorKind::UnterminatedString),
        TokenError::NewlineInTableKey(at) => make_error(input, at, ErrorKind::NewlineInTableKey),
        TokenError::Wanted { at, expected, found } => {
            make_error(input, at, ErrorKind::Wanted { expected, found })
        }
        TokenError::EmptyTableKey(at) => make_error(input, at, ErrorKind::EmptyTableKey),
        TokenError::MultilineStringKey(at) => make_error(input, at, ErrorKind::MultilineStringKey),
    }
}

// ---------------------------------------------------------------------------
// Parsed document model

#[derive(Debug, Clone)]
pub enum E {
    Integer(i64),
    Float(f64),
    Boolean(bool),
    Str(String),
    Datetime(String),
    Array(Vec<Value>),
    InlineTable(Vec<(String, Value)>),
    DottedTable(Vec<(String, Value)>),
}

#[derive(Debug, Clone)]
pub struct Value {
    pub e: E,
    pub start: usize,
    pub end: usize,
}

impl Value {
    fn same_type(&self, other: &Value) -> bool {
        matches!(
            (&self.e, &other.e),
            (E::Str(..), E::Str(..))
                | (E::Integer(..), E::Integer(..))
                | (E::Float(..), E::Float(..))
                | (E::Boolean(..), E::Boolean(..))
                | (E::Datetime(..), E::Datetime(..))
                | (E::Array(..), E::Array(..))
                | (E::InlineTable(..), E::InlineTable(..))
                | (E::DottedTable(..), E::DottedTable(..))
        )
    }
}

struct Table {
    at: usize,
    header: Vec<String>,
    values: Option<Vec<(String, Value)>>,
    array: bool,
}

enum Line<'a> {
    Table {
        at: usize,
        header: Header<'a>,
        array: bool,
    },
    KeyValue(Vec<(Span, String)>, Value),
}

struct Header<'a> {
    first: bool,
    array: bool,
    tokens: Tokenizer<'a>,
}

impl<'a> Header<'a> {
    fn next(&mut self) -> Result<Option<(Span, String)>, TokenError> {
        self.tokens.eat_whitespace();
        if self.first || self.tokens.eat(Token::Period)? {
            self.first = false;
            self.tokens.eat_whitespace();
            self.tokens.table_key().map(Some)
        } else {
            self.tokens.expect(Token::RightBracket)?;
            if self.array {
                self.tokens.expect(Token::RightBracket)?;
            }
            self.tokens.eat_whitespace();
            if !self.tokens.eat_comment()? {
                self.tokens.eat_newline_or_eof()?;
            }
            Ok(None)
        }
    }
}

struct Parser<'a> {
    input: &'a str,
    tokens: Tokenizer<'a>,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Parser<'a> {
        Parser {
            input,
            tokens: Tokenizer::new(input),
        }
    }

    fn err(&self, at: usize, kind: ErrorKind) -> DeError {
        make_error(self.input, at, kind)
    }

    fn terr(&self, e: TokenError) -> DeError {
        token_error(self.input, e)
    }

    fn substr_offset(&self, s: &str) -> usize {
        s.as_ptr() as usize - self.input.as_ptr() as usize
    }

    fn next(&mut self) -> Result<Option<(Span, Token<'a>)>, DeError> {
        self.tokens.next().map_err(|e| token_error(self.input, e))
    }

    fn peek(&mut self) -> Result<Option<(Span, Token<'a>)>, DeError> {
        self.tokens.peek().map_err(|e| token_error(self.input, e))
    }

    fn eat(&mut self, t: Token<'a>) -> Result<bool, DeError> {
        self.tokens.eat(t).map_err(|e| token_error(self.input, e))
    }

    fn eat_spanned(&mut self, t: Token<'a>) -> Result<Option<Span>, DeError> {
        self.tokens.eat_spanned(t).map_err(|e| token_error(self.input, e))
    }

    fn expect(&mut self, t: Token<'a>) -> Result<(), DeError> {
        self.tokens.expect(t).map_err(|e| token_error(self.input, e))
    }

    fn expect_spanned(&mut self, t: Token<'a>) -> Result<Span, DeError> {
        self.tokens.expect_spanned(t).map_err(|e| token_error(self.input, e))
    }

    fn eat_whitespace(&mut self) {
        self.tokens.eat_whitespace();
    }

    fn eat_comment(&mut self) -> Result<bool, DeError> {
        self.tokens.eat_comment().map_err(|e| token_error(self.input, e))
    }

    fn eat_newline_or_eof(&mut self) -> Result<(), DeError> {
        self.tokens
            .eat_newline_or_eof()
            .map_err(|e| token_error(self.input, e))
    }

    fn eof(&self) -> DeError {
        self.err(self.input.len(), ErrorKind::UnexpectedEof)
    }

    fn tables(&mut self) -> Result<Vec<Table>, DeError> {
        let mut tables = Vec::new();
        let mut cur_table = Table {
            at: 0,
            header: Vec::new(),
            values: None,
            array: false,
        };
        while let Some(line) = self.line()? {
            match line {
                Line::Table {
                    at,
                    mut header,
                    array,
                } => {
                    if !cur_table.header.is_empty() || cur_table.values.is_some() {
                        tables.push(cur_table);
                    }
                    cur_table = Table {
                        at,
                        header: Vec::new(),
                        values: Some(Vec::new()),
                        array,
                    };
                    loop {
                        let part = header.next().map_err(|e| self.terr(e))?;
                        match part {
                            Some(part) => cur_table.header.push(part.1),
                            None => break,
                        }
                    }
                }
                Line::KeyValue(key, value) => {
                    if cur_table.values.is_none() {
                        cur_table.values = Some(Vec::new());
                    }
                    self.add_dotted_key(key, value, cur_table.values.as_mut().unwrap())?;
                }
            }
        }
        if !cur_table.header.is_empty() || cur_table.values.is_some() {
            tables.push(cur_table);
        }
        Ok(tables)
    }

    fn line(&mut self) -> Result<Option<Line<'a>>, DeError> {
        loop {
            self.eat_whitespace();
            if self.eat_comment()? {
                continue;
            }
            if self.eat(Token::Newline)? {
                continue;
            }
            break;
        }
        match self.peek()? {
            Some((_, Token::LeftBracket)) => self.table_header().map(Some),
            Some(_) => self.key_value().map(Some),
            None => Ok(None),
        }
    }

    fn table_header(&mut self) -> Result<Line<'a>, DeError> {
        let start = self.tokens.current();
        self.expect(Token::LeftBracket)?;
        let array = self.eat(Token::LeftBracket)?;
        let ret = Header {
            first: true,
            array,
            tokens: self.tokens,
        };
        self.tokens.skip_to_newline();
        Ok(Line::Table {
            at: start,
            header: ret,
            array,
        })
    }

    fn key_value(&mut self) -> Result<Line<'a>, DeError> {
        let key = self.dotted_key()?;
        self.eat_whitespace();
        self.expect(Token::Equals)?;
        self.eat_whitespace();
        let value = self.value()?;
        self.eat_whitespace();
        if !self.eat_comment()? {
            self.eat_newline_or_eof()?;
        }
        Ok(Line::KeyValue(key, value))
    }

    fn value(&mut self) -> Result<Value, DeError> {
        let at = self.tokens.current();
        let value = match self.next()? {
            Some((Span { start, end }, Token::Str { val, .. })) => Value {
                e: E::Str(val),
                start,
                end,
            },
            Some((Span { start, end }, Token::Keylike("true"))) => Value {
                e: E::Boolean(true),
                start,
                end,
            },
            Some((Span { start, end }, Token::Keylike("false"))) => Value {
                e: E::Boolean(false),
                start,
                end,
            },
            Some((span, Token::Keylike(key))) => self.number_or_date(span, key)?,
            Some((span, Token::Plus)) => self.number_leading_plus(span)?,
            Some((Span { start, .. }, Token::LeftBrace)) => {
                let (Span { end, .. }, table) = self.inline_table()?;
                Value {
                    e: E::InlineTable(table),
                    start,
                    end,
                }
            }
            Some((Span { start, .. }, Token::LeftBracket)) => {
                let (Span { end, .. }, array) = self.array()?;
                Value {
                    e: E::Array(array),
                    start,
                    end,
                }
            }
            Some(token) => {
                return Err(self.err(
                    at,
                    ErrorKind::Wanted {
                        expected: "a value",
                        found: token.1.describe(),
                    },
                ))
            }
            None => return Err(self.eof()),
        };
        Ok(value)
    }

    fn number_or_date(&mut self, span: Span, s: &'a str) -> Result<Value, DeError> {
        if s.contains('T') || (s.len() > 1 && s[1..].contains('-') && !s.contains("e-")) {
            let (sp, d) = self.datetime(span, s, false)?;
            Ok(Value {
                e: E::Datetime(d.to_string()),
                start: sp.start,
                end: sp.end,
            })
        } else if self.eat(Token::Colon)? {
            let (sp, d) = self.datetime(span, s, true)?;
            Ok(Value {
                e: E::Datetime(d.to_string()),
                start: sp.start,
                end: sp.end,
            })
        } else {
            self.number(span, s)
        }
    }

    fn number(&mut self, Span { start, end }: Span, s: &'a str) -> Result<Value, DeError> {
        let to_int = |i: i64| Value {
            e: E::Integer(i),
            start,
            end,
        };
        if let Some(rest) = s.strip_prefix("0x") {
            self.integer(rest, 16).map(to_int)
        } else if let Some(rest) = s.strip_prefix("0o") {
            self.integer(rest, 8).map(to_int)
        } else if let Some(rest) = s.strip_prefix("0b") {
            self.integer(rest, 2).map(to_int)
        } else if s.contains('e') || s.contains('E') {
            let f = self.float(s, None)?;
            Ok(Value {
                e: E::Float(f),
                start,
                end,
            })
        } else if self.eat(Token::Period)? {
            let at = self.tokens.current();
            match self.next()? {
                Some((Span { start, end }, Token::Keylike(after))) => {
                    let f = self.float(s, Some(after))?;
                    Ok(Value {
                        e: E::Float(f),
                        start,
                        end,
                    })
                }
                _ => Err(self.err(at, ErrorKind::NumberInvalid)),
            }
        } else if s == "inf" {
            Ok(Value {
                e: E::Float(f64::INFINITY),
                start,
                end,
            })
        } else if s == "-inf" {
            Ok(Value {
                e: E::Float(f64::NEG_INFINITY),
                start,
                end,
            })
        } else if s == "nan" {
            Ok(Value {
                e: E::Float(f64::NAN),
                start,
                end,
            })
        } else if s == "-nan" {
            Ok(Value {
                e: E::Float(-f64::NAN),
                start,
                end,
            })
        } else {
            self.integer(s, 10).map(to_int)
        }
    }

    fn number_leading_plus(&mut self, Span { start, .. }: Span) -> Result<Value, DeError> {
        let start_token = self.tokens.current();
        match self.next()? {
            Some((Span { end, .. }, Token::Keylike(s))) => self.number(Span { start, end }, s),
            _ => Err(self.err(start_token, ErrorKind::NumberInvalid)),
        }
    }

    fn integer(&self, s: &'a str, radix: u32) -> Result<i64, DeError> {
        let allow_sign = radix == 10;
        let allow_leading_zeros = radix != 10;
        let (prefix, suffix) = self.parse_integer(s, allow_sign, allow_leading_zeros, radix)?;
        let start = self.substr_offset(s);
        if !suffix.is_empty() {
            return Err(self.err(start, ErrorKind::NumberInvalid));
        }
        let cleaned = prefix.replace('_', "");
        let cleaned = cleaned.trim_start_matches('+');
        i64::from_str_radix(cleaned, radix).map_err(|_| self.err(start, ErrorKind::NumberInvalid))
    }

    fn parse_integer(
        &self,
        s: &'a str,
        allow_sign: bool,
        allow_leading_zeros: bool,
        radix: u32,
    ) -> Result<(&'a str, &'a str), DeError> {
        let start = self.substr_offset(s);
        let mut first = true;
        let mut first_zero = false;
        let mut underscore = false;
        let mut end = s.len();
        for (i, c) in s.char_indices() {
            let at = i + start;
            if i == 0 && (c == '+' || c == '-') && allow_sign {
                continue;
            }
            if c == '0' && first {
                first_zero = true;
            } else if c.to_digit(radix).is_some() {
                if !first && first_zero && !allow_leading_zeros {
                    return Err(self.err(at, ErrorKind::NumberInvalid));
                }
                underscore = false;
            } else if c == '_' && first {
                return Err(self.err(at, ErrorKind::NumberInvalid));
            } else if c == '_' && !underscore {
                underscore = true;
            } else {
                end = i;
                break;
            }
            first = false;
        }
        if first || underscore {
            return Err(self.err(start, ErrorKind::NumberInvalid));
        }
        Ok((&s[..end], &s[end..]))
    }

    fn float(&mut self, s: &'a str, after_decimal: Option<&'a str>) -> Result<f64, DeError> {
        let (integral, mut suffix) = self.parse_integer(s, true, false, 10)?;
        let start = self.substr_offset(integral);

        let mut fraction = None;
        if let Some(after) = after_decimal {
            if !suffix.is_empty() {
                return Err(self.err(start, ErrorKind::NumberInvalid));
            }
            let (a, b) = self.parse_integer(after, false, true, 10)?;
            fraction = Some(a);
            suffix = b;
        }

        let mut exponent = None;
        if suffix.starts_with('e') || suffix.starts_with('E') {
            let (a, b) = if suffix.len() == 1 {
                self.eat(Token::Plus)?;
                match self.next()? {
                    Some((_, Token::Keylike(s))) => self.parse_integer(s, false, false, 10)?,
                    _ => return Err(self.err(start, ErrorKind::NumberInvalid)),
                }
            } else {
                self.parse_integer(&suffix[1..], true, false, 10)?
            };
            if !b.is_empty() {
                return Err(self.err(start, ErrorKind::NumberInvalid));
            }
            exponent = Some(a);
        } else if !suffix.is_empty() {
            return Err(self.err(start, ErrorKind::NumberInvalid));
        }

        let mut number: String = integral
            .trim_start_matches('+')
            .chars()
            .filter(|c| *c != '_')
            .collect();
        if let Some(fraction) = fraction {
            number.push('.');
            number.extend(fraction.chars().filter(|c| *c != '_'));
        }
        if let Some(exponent) = exponent {
            number.push('E');
            number.extend(exponent.chars().filter(|c| *c != '_'));
        }
        match number.parse::<f64>() {
            Ok(n) if n.is_finite() => Ok(n),
            _ => Err(self.err(start, ErrorKind::NumberInvalid)),
        }
    }

    fn datetime(
        &mut self,
        mut span: Span,
        date: &'a str,
        colon_eaten: bool,
    ) -> Result<(Span, &'a str), DeError> {
        let start = self.substr_offset(date);

        let mut lookahead = self.tokens;
        if let Ok(Some((_, Token::Whitespace(" ")))) = lookahead.next() {
            if let Ok(Some((_, Token::Keylike(_)))) = lookahead.next() {
                self.next()?;
                self.next()?;
            }
        }

        if colon_eaten || self.eat(Token::Colon)? {
            match self.next()? {
                Some((_, Token::Keylike(_))) => {}
                _ => return Err(self.err(start, ErrorKind::DateInvalid)),
            }
            self.expect(Token::Colon)?;
            match self.next()? {
                Some((Span { end, .. }, Token::Keylike(_))) => {
                    span.end = end;
                }
                _ => return Err(self.err(start, ErrorKind::DateInvalid)),
            }
            if self.eat(Token::Period)? {
                match self.next()? {
                    Some((Span { end, .. }, Token::Keylike(_))) => {
                        span.end = end;
                    }
                    _ => return Err(self.err(start, ErrorKind::DateInvalid)),
                }
            }
            if self.eat(Token::Plus)? {
                match self.next()? {
                    Some((Span { end, .. }, Token::Keylike(_))) => {
                        span.end = end;
                    }
                    _ => return Err(self.err(start, ErrorKind::DateInvalid)),
                }
            }
            if self.eat(Token::Colon)? {
                match self.next()? {
                    Some((Span { end, .. }, Token::Keylike(_))) => {
                        span.end = end;
                    }
                    _ => return Err(self.err(start, ErrorKind::DateInvalid)),
                }
            }
        }
        let end = self.tokens.current();
        Ok((span, &self.input[start..end]))
    }

    fn inline_table(&mut self) -> Result<(Span, Vec<(String, Value)>), DeError> {
        let mut ret = Vec::new();
        self.eat_whitespace();
        if let Some(span) = self.eat_spanned(Token::RightBrace)? {
            return Ok((span, ret));
        }
        loop {
            let key = self.dotted_key()?;
            self.eat_whitespace();
            self.expect(Token::Equals)?;
            self.eat_whitespace();
            let value = self.value()?;
            self.add_dotted_key(key, value, &mut ret)?;
            self.eat_whitespace();
            if let Some(span) = self.eat_spanned(Token::RightBrace)? {
                return Ok((span, ret));
            }
            self.expect(Token::Comma)?;
            self.eat_whitespace();
        }
    }

    fn array_intermediate(&mut self) -> Result<(), DeError> {
        loop {
            self.eat_whitespace();
            if !self.eat(Token::Newline)? && !self.eat_comment()? {
                break;
            }
        }
        Ok(())
    }

    fn array(&mut self) -> Result<(Span, Vec<Value>), DeError> {
        let mut ret: Vec<Value> = Vec::new();
        loop {
            self.array_intermediate()?;
            if let Some(span) = self.eat_spanned(Token::RightBracket)? {
                return Ok((span, ret));
            }
            let at = self.tokens.current();
            let value = self.value()?;
            if let Some(last) = ret.last() {
                if !value.same_type(last) {
                    return Err(self.err(at, ErrorKind::MixedArrayType));
                }
            }
            ret.push(value);
            self.array_intermediate()?;
            if !self.eat(Token::Comma)? {
                break;
            }
        }
        self.array_intermediate()?;
        let span = self.expect_spanned(Token::RightBracket)?;
        Ok((span, ret))
    }

    fn table_key(&mut self) -> Result<(Span, String), DeError> {
        self.tokens.table_key().map_err(|e| token_error(self.input, e))
    }

    fn dotted_key(&mut self) -> Result<Vec<(Span, String)>, DeError> {
        let mut result = Vec::new();
        result.push(self.table_key()?);
        self.eat_whitespace();
        while self.eat(Token::Period)? {
            self.eat_whitespace();
            result.push(self.table_key()?);
            self.eat_whitespace();
        }
        Ok(result)
    }

    fn add_dotted_key(
        &self,
        mut key_parts: Vec<(Span, String)>,
        value: Value,
        values: &mut Vec<(String, Value)>,
    ) -> Result<(), DeError> {
        let key = key_parts.remove(0);
        if key_parts.is_empty() {
            values.push((key.1, value));
            return Ok(());
        }
        let pos = values.iter().position(|(k, _)| *k == key.1);
        if let Some(p) = pos {
            match values[p].1.e {
                E::DottedTable(ref mut v) => {
                    return self.add_dotted_key(key_parts, value, v);
                }
                _ => {
                    return Err(self.err(values[p].1.start, ErrorKind::DottedKeyInvalidType));
                }
            }
        }
        let table_values = Value {
            e: E::DottedTable(Vec::new()),
            start: value.start,
            end: value.end,
        };
        values.push((key.1, table_values));
        let last_i = values.len() - 1;
        if let E::DottedTable(ref mut v) = values[last_i].1.e {
            self.add_dotted_key(key_parts, value, v)?;
        }
        Ok(())
    }
}

// ---------------------------------------------------------------------------
// Deserialization machinery (serde-like visitors)

pub enum Unexp {
    Bool(bool),
    Signed(i64),
    Float(f64),
    Str(String),
    Map,
    Seq,
}

impl std::fmt::Display for Unexp {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            Unexp::Bool(b) => write!(f, "boolean `{}`", b),
            Unexp::Signed(i) => write!(f, "integer `{}`", i),
            Unexp::Float(x) => write!(f, "floating point `{}`", x),
            Unexp::Str(s) => write!(f, "string {:?}", s),
            Unexp::Map => write!(f, "map"),
            Unexp::Seq => write!(f, "sequence"),
        }
    }
}

pub fn invalid_type(u: Unexp, exp: &str) -> DeError {
    DeError::custom(format!("invalid type: {}, expected {}", u, exp))
}

pub fn invalid_value(u: Unexp, exp: &str) -> DeError {
    DeError::custom(format!("invalid value: {}, expected {}", u, exp))
}

pub fn invalid_length(len: usize, exp: &str) -> DeError {
    DeError::custom(format!("invalid length {}, expected {}", len, exp))
}

pub fn missing_field(f: &str) -> DeError {
    DeError::custom(format!("missing field `{}`", f))
}

pub fn duplicate_field(f: &str) -> DeError {
    DeError::custom(format!("duplicate field `{}`", f))
}

pub struct MapVisitor<'t> {
    values: std::vec::IntoIter<(String, Value)>,
    next_value: Option<(String, Value)>,
    depth: usize,
    cur: usize,
    cur_parent: usize,
    max: usize,
    array: bool,
    tables: &'t mut Vec<Table>,
    input: &'t str,
}

pub enum Src<'t> {
    Val(Value),
    Table(MapVisitor<'t>),
}

pub trait MapAccess {
    fn next_key(&mut self) -> Result<Option<String>, DeError>;
    fn next_value<T, F>(&mut self, f: F) -> Result<T, DeError>
    where
        F: FnOnce(Src<'_>) -> Result<T, DeError>;
}

pub trait SeqAccess {
    fn next_element<T, F>(&mut self, f: F) -> Result<Option<T>, DeError>
    where
        F: FnOnce(Src<'_>) -> Result<T, DeError>;
}

fn headers_equal(a: &[String], b: &[String]) -> bool {
    a == b
}

impl<'t> MapAccess for MapVisitor<'t> {
    fn next_key(&mut self) -> Result<Option<String>, DeError> {
        if self.cur_parent == self.max || self.cur == self.max {
            return Ok(None);
        }
        loop {
            if let Some((key, value)) = self.values.next() {
                let ret = key.clone();
                self.next_value = Some((key, value));
                return Ok(Some(ret));
            }
            let next_table = {
                let prefix = &self.tables[self.cur_parent].header[..self.depth.min(self.tables[self.cur_parent].header.len())];
                let depth = self.depth;
                self.tables[self.cur..self.max]
                    .iter()
                    .enumerate()
                    .find(|(_, t)| {
                        if t.values.is_none() {
                            return false;
                        }
                        match t.header.get(..depth) {
                            Some(h) => h == prefix,
                            None => false,
                        }
                    })
                    .map(|(i, _)| i + self.cur)
            };
            let pos = match next_table {
                Some(p) => p,
                None => return Ok(None),
            };
            self.cur = pos;
            if self.cur_parent != pos {
                if headers_equal(&self.tables[self.cur_parent].header, &self.tables[pos].header) {
                    let at = self.tables[pos].at;
                    let name = self.tables[pos].header.join(".");
                    return Err(make_error(self.input, at, ErrorKind::DuplicateTable(name)));
                }
                let parent_len = self.tables[self.cur_parent].header.len();
                let cur_len = self.tables[pos].header.len();
                if cur_len < parent_len {
                    self.cur_parent = pos;
                }
            }
            let depth = self.depth;
            let table = &mut self.tables[pos];
            if depth != table.header.len() {
                let key = table.header[depth].clone();
                return Ok(Some(key));
            }
            if table.array {
                let at = table.at;
                return Err(make_error(self.input, at, ErrorKind::RedefineAsArray));
            }
            let vals = table.values.take().unwrap_or_default();
            self.values = vals.into_iter();
        }
    }

    fn next_value<T, F>(&mut self, f: F) -> Result<T, DeError>
    where
        F: FnOnce(Src<'_>) -> Result<T, DeError>,
    {
        if let Some((k, v)) = self.next_value.take() {
            return f(Src::Val(v)).map_err(|mut e| {
                e.add_key_context(&k);
                e
            });
        }
        let array = self.tables[self.cur].array
            && self.depth == self.tables[self.cur].header.len().wrapping_sub(1);
        self.cur += 1;
        let depth = self.depth;
        let res = {
            let sub = MapVisitor {
                values: Vec::new().into_iter(),
                next_value: None,
                depth: depth + if array { 0 } else { 1 },
                cur_parent: self.cur - 1,
                cur: 0,
                max: self.max,
                array,
                tables: &mut *self.tables,
                input: self.input,
            };
            f(Src::Table(sub))
        };
        res.map_err(|mut e| {
            let key = self.tables[self.cur - 1].header[depth].clone();
            e.add_key_context(&key);
            e
        })
    }
}

impl<'t> SeqAccess for MapVisitor<'t> {
    fn next_element<T, F>(&mut self, f: F) -> Result<Option<T>, DeError>
    where
        F: FnOnce(Src<'_>) -> Result<T, DeError>,
    {
        if self.cur_parent == self.max {
            return Ok(None);
        }
        let parent_header = self.tables[self.cur_parent].header.clone();
        let next = (self.cur_parent + 1..self.max)
            .find(|&i| self.tables[i].array && self.tables[i].header == parent_header)
            .unwrap_or(self.max);
        let values = self.tables[self.cur_parent].values.take().unwrap_or_default();
        let ret = {
            let sub = MapVisitor {
                values: values.into_iter(),
                next_value: None,
                depth: self.depth + 1,
                cur_parent: self.cur_parent,
                max: next,
                cur: 0,
                array: false,
                tables: &mut *self.tables,
                input: self.input,
            };
            f(Src::Table(sub))?
        };
        self.cur_parent = next;
        Ok(Some(ret))
    }
}

struct InlineTableDe {
    values: VecDeque<(String, Value)>,
    next_value: Option<Value>,
}

impl MapAccess for InlineTableDe {
    fn next_key(&mut self) -> Result<Option<String>, DeError> {
        match self.values.pop_front() {
            Some((k, v)) => {
                self.next_value = Some(v);
                Ok(Some(k))
            }
            None => Ok(None),
        }
    }
    fn next_value<T, F>(&mut self, f: F) -> Result<T, DeError>
    where
        F: FnOnce(Src<'_>) -> Result<T, DeError>,
    {
        let v = self.next_value.take().expect("Unable to read table values");
        f(Src::Val(v))
    }
}

struct DatetimeDe {
    date: String,
    visited: bool,
}

impl MapAccess for DatetimeDe {
    fn next_key(&mut self) -> Result<Option<String>, DeError> {
        if self.visited {
            return Ok(None);
        }
        self.visited = true;
        Ok(Some("$__toml_private_datetime".to_string()))
    }
    fn next_value<T, F>(&mut self, f: F) -> Result<T, DeError>
    where
        F: FnOnce(Src<'_>) -> Result<T, DeError>,
    {
        f(Src::Val(Value {
            e: E::Str(self.date.clone()),
            start: 0,
            end: 0,
        }))
    }
}

struct ValueSeq {
    iter: std::vec::IntoIter<Value>,
    count: usize,
}

impl SeqAccess for ValueSeq {
    fn next_element<T, F>(&mut self, f: F) -> Result<Option<T>, DeError>
    where
        F: FnOnce(Src<'_>) -> Result<T, DeError>,
    {
        match self.iter.next() {
            Some(v) => {
                self.count += 1;
                f(Src::Val(v)).map(Some)
            }
            None => Ok(None),
        }
    }
}

impl ValueSeq {
    fn end(self) -> Result<(), DeError> {
        let remaining = self.iter.count();
        if remaining == 0 {
            Ok(())
        } else {
            let exp = if self.count == 1 {
                "1 element in sequence".to_string()
            } else {
                format!("{} elements in sequence", self.count)
            };
            Err(invalid_length(self.count + remaining, &exp))
        }
    }
}

pub trait Visitor: Sized {
    type Value;
    fn expecting(&self) -> String;
    fn visit_i64(self, v: i64) -> Result<Self::Value, DeError> {
        Err(invalid_type(Unexp::Signed(v), &self.expecting()))
    }
    fn visit_f64(self, v: f64) -> Result<Self::Value, DeError> {
        Err(invalid_type(Unexp::Float(v), &self.expecting()))
    }
    fn visit_bool(self, v: bool) -> Result<Self::Value, DeError> {
        Err(invalid_type(Unexp::Bool(v), &self.expecting()))
    }
    fn visit_str(self, v: String) -> Result<Self::Value, DeError> {
        Err(invalid_type(Unexp::Str(v), &self.expecting()))
    }
    fn visit_map<M: MapAccess>(self, _m: &mut M) -> Result<Self::Value, DeError> {
        Err(invalid_type(Unexp::Map, &self.expecting()))
    }
    fn visit_seq<S: SeqAccess>(self, _s: &mut S) -> Result<Self::Value, DeError> {
        Err(invalid_type(Unexp::Seq, &self.expecting()))
    }
}

pub fn deserialize<V: Visitor>(src: Src<'_>, v: V) -> Result<V::Value, DeError> {
    match src {
        Src::Val(val) => match val.e {
            E::Integer(i) => v.visit_i64(i),
            E::Float(f) => v.visit_f64(f),
            E::Boolean(b) => v.visit_bool(b),
            E::Str(s) => v.visit_str(s),
            E::Datetime(s) => v.visit_map(&mut DatetimeDe {
                date: s,
                visited: false,
            }),
            E::Array(values) => {
                let mut s = ValueSeq {
                    iter: values.into_iter(),
                    count: 0,
                };
                let r = v.visit_seq(&mut s)?;
                s.end()?;
                Ok(r)
            }
            E::InlineTable(values) | E::DottedTable(values) => v.visit_map(&mut InlineTableDe {
                values: values.into_iter().collect(),
                next_value: None,
            }),
        },
        Src::Table(mut mv) => {
            if mv.array {
                v.visit_seq(&mut mv)
            } else {
                v.visit_map(&mut mv)
            }
        }
    }
}

// Common visitors -------------------------------------------------------------

pub struct IgnoredAny;

impl Visitor for IgnoredAny {
    type Value = ();
    fn expecting(&self) -> String {
        "anything at all".to_string()
    }
    fn visit_i64(self, _v: i64) -> Result<(), DeError> {
        Ok(())
    }
    fn visit_f64(self, _v: f64) -> Result<(), DeError> {
        Ok(())
    }
    fn visit_bool(self, _v: bool) -> Result<(), DeError> {
        Ok(())
    }
    fn visit_str(self, _v: String) -> Result<(), DeError> {
        Ok(())
    }
    fn visit_map<M: MapAccess>(self, m: &mut M) -> Result<(), DeError> {
        while m.next_key()?.is_some() {
            m.next_value(|s| deserialize(s, IgnoredAny))?;
        }
        Ok(())
    }
    fn visit_seq<S: SeqAccess>(self, s: &mut S) -> Result<(), DeError> {
        while s.next_element(|x| deserialize(x, IgnoredAny))?.is_some() {}
        Ok(())
    }
}

pub struct StringVisitor;

impl Visitor for StringVisitor {
    type Value = String;
    fn expecting(&self) -> String {
        "a string".to_string()
    }
    fn visit_str(self, v: String) -> Result<String, DeError> {
        Ok(v)
    }
}

pub struct UsizeVisitor;

impl Visitor for UsizeVisitor {
    type Value = usize;
    fn expecting(&self) -> String {
        "usize".to_string()
    }
    fn visit_i64(self, v: i64) -> Result<usize, DeError> {
        if v >= 0 {
            Ok(v as usize)
        } else {
            Err(invalid_value(Unexp::Signed(v), &self.expecting()))
        }
    }
}

pub struct VecStringVisitor;

impl Visitor for VecStringVisitor {
    type Value = Vec<String>;
    fn expecting(&self) -> String {
        "a sequence".to_string()
    }
    fn visit_seq<S: SeqAccess>(self, s: &mut S) -> Result<Vec<String>, DeError> {
        let mut out = Vec::new();
        while let Some(v) = s.next_element(|x| deserialize(x, StringVisitor))? {
            out.push(v);
        }
        Ok(out)
    }
}

/// Parse a document and run the root visitor over it.
pub fn from_str<V: Visitor>(input: &str, v: V) -> Result<V::Value, DeError> {
    let mut p = Parser::new(input);
    let mut tables = p.tables()?;
    let max = tables.len();
    let mut mv = MapVisitor {
        values: Vec::new().into_iter(),
        next_value: None,
        depth: 0,
        cur: 0,
        cur_parent: 0,
        max,
        array: false,
        tables: &mut tables,
        input,
    };
    v.visit_map(&mut mv)
}
