//! Configuration model, loading and saving.

use crate::toml_de::{
    self, deserialize, duplicate_field, invalid_length, missing_field, DeError, IgnoredAny,
    MapAccess, SeqAccess, StringVisitor, UsizeVisitor, VecStringVisitor, Visitor,
};
use crate::toml_ser;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Default)]
pub struct Script {
    pub command: String,
    pub description: Option<String>,
    pub reference: Option<String>,
    pub tags: Option<Vec<String>>,
}

#[derive(Debug, Clone, Default)]
pub struct Defaults {
    pub interpreter: Option<Vec<String>>,
    pub command_width: Option<usize>,
}

#[derive(Debug, Clone, Default)]
pub struct Config {
    pub scripts: BTreeMap<String, Script>,
    pub default: Defaults,
}

// ---------------------------------------------------------------------------
// Deserialization

struct ScriptVisitor;

impl Visitor for ScriptVisitor {
    type Value = Script;
    fn expecting(&self) -> String {
        "struct Script".to_string()
    }
    fn visit_seq<S: SeqAccess>(self, s: &mut S) -> Result<Script, DeError> {
        let exp = "struct Script with 4 elements";
        let command = match s.next_element(|x| deserialize(x, StringVisitor))? {
            Some(v) => v,
            None => return Err(invalid_length(0, exp)),
        };
        let description = match s.next_element(|x| deserialize(x, StringVisitor))? {
            Some(v) => Some(v),
            None => return Err(invalid_length(1, exp)),
        };
        let reference = match s.next_element(|x| deserialize(x, StringVisitor))? {
            Some(v) => Some(v),
            None => return Err(invalid_length(2, exp)),
        };
        let tags = match s.next_element(|x| deserialize(x, VecStringVisitor))? {
            Some(v) => Some(v),
            None => return Err(invalid_length(3, exp)),
        };
        Ok(Script {
            command,
            description,
            reference,
            tags,
        })
    }
    fn visit_map<M: MapAccess>(self, m: &mut M) -> Result<Script, DeError> {
        let mut command: Option<String> = None;
        let mut description: Option<String> = None;
        let mut reference: Option<String> = None;
        let mut tags: Option<Vec<String>> = None;
        while let Some(key) = m.next_key()? {
            match key.as_str() {
                "command" => {
                    if command.is_some() {
                        return Err(duplicate_field("command"));
                    }
                    command = Some(m.next_value(|x| deserialize(x, StringVisitor))?);
                }
                "description" => {
                    if description.is_some() {
                        return Err(duplicate_field("description"));
                    }
                    description = Some(m.next_value(|x| deserialize(x, StringVisitor))?);
                }
                "reference" => {
                    if reference.is_some() {
                        return Err(duplicate_field("reference"));
                    }
                    reference = Some(m.next_value(|x| deserialize(x, StringVisitor))?);
                }
                "tags" => {
                    if tags.is_some() {
                        return Err(duplicate_field("tags"));
                    }
                    tags = Some(m.next_value(|x| deserialize(x, VecStringVisitor))?);
                }
                _ => {
                    m.next_value(|x| deserialize(x, IgnoredAny))?;
                }
            }
        }
        let command = match command {
            Some(c) => c,
            None => return Err(missing_field("command")),
        };
        Ok(Script {
            command,
            description,
            reference,
            tags,
        })
    }
}

struct DefaultsVisitor;

impl Visitor for DefaultsVisitor {
    type Value = Defaults;
    fn expecting(&self) -> String {
        "struct ConfigDefaultOpts".to_string()
    }
    fn visit_seq<S: SeqAccess>(self, s: &mut S) -> Result<Defaults, DeError> {
        let exp = "struct ConfigDefaultOpts with 2 elements";
        let interpreter = match s.next_element(|x| deserialize(x, VecStringVisitor))? {
            Some(v) => Some(v),
            None => return Err(invalid_length(0, exp)),
        };
