            None => return Err(invalid_length(1, exp)),
        };
        Ok(Defaults {
            interpreter,
            command_width,
        })
    }
    fn visit_map<M: MapAccess>(self, m: &mut M) -> Result<Defaults, DeError> {
        let mut interpreter: Option<Vec<String>> = None;
        let mut command_width: Option<usize> = None;
        while let Some(key) = m.next_key()? {
            match key.as_str() {
                "interpreter" => {
                    if interpreter.is_some() {
                        return Err(duplicate_field("interpreter"));
                    }
                    interpreter = Some(m.next_value(|x| deserialize(x, VecStringVisitor))?);
                }
                "command_width" => {
                    if command_width.is_some() {
                        return Err(duplicate_field("command_width"));
                    }
                    command_width = Some(m.next_value(|x| deserialize(x, UsizeVisitor))?);
                }
                _ => {
                    m.next_value(|x| deserialize(x, IgnoredAny))?;
                }
            }
        }
        Ok(Defaults {
            interpreter,
            command_width,
        })
    }
}

struct ScriptsVisitor;

impl Visitor for ScriptsVisitor {
    type Value = BTreeMap<String, Script>;
    fn expecting(&self) -> String {
        "map is expected".to_string()
    }
    fn visit_map<M: MapAccess>(self, m: &mut M) -> Result<Self::Value, DeError> {
        let mut out = BTreeMap::new();
        while let Some(key) = m.next_key()? {
            let v = m.next_value(|x| deserialize(x, ScriptVisitor))?;
            out.insert(key, v);
        }
        Ok(out)
    }
}

struct ConfigVisitor;

impl Visitor for ConfigVisitor {
    type Value = Config;
    fn expecting(&self) -> String {
        "struct Config".to_string()
    }
    fn visit_map<M: MapAccess>(self, m: &mut M) -> Result<Config, DeError> {
        let mut scripts: Option<BTreeMap<String, Script>> = None;
        let mut default: Option<Defaults> = None;
        while let Some(key) = m.next_key()? {
            match key.as_str() {
                "scripts" => {
                    if scripts.is_some() {
                        return Err(duplicate_field("scripts"));
                    }
                    scripts = Some(m.next_value(|x| deserialize(x, ScriptsVisitor))?);
                }
                "default" => {
                    if default.is_some() {
                        return Err(duplicate_field("default"));
                    }
                    default = Some(m.next_value(|x| deserialize(x, DefaultsVisitor))?);
                }
                _ => {
                    m.next_value(|x| deserialize(x, IgnoredAny))?;
                }
            }
        }
        Ok(Config {
            scripts: scripts.unwrap_or_default(),
            default: default.unwrap_or_default(),
        })
    }
}

pub fn parse_config(input: &str) -> Result<Config, DeError> {
    toml_de::from_str(input, ConfigVisitor)
}

// ---------------------------------------------------------------------------
// Serialization

pub fn serialize_config(cfg: &Config) -> String {
    let mut out = String::new();
    let mut first = true;
    let mut header = |out: &mut String, name: &str| {
        if !first {
            out.push('\n');
        }
        first = false;
        out.push('[');
        out.push_str(name);
        out.push_str("]\n");
    };
    if cfg.scripts.is_empty() {
        header(&mut out, "scripts");
    }
    for (alias, s) in &cfg.scripts {
        let mut name = String::from("scripts.");
        toml_ser::emit_key(&mut name, alias);
        header(&mut out, &name);
        toml_ser::emit_string_kv(&mut out, "command", &s.command);
        if let Some(d) = &s.description {
            toml_ser::emit_string_kv(&mut out, "description", d);
        }
        if let Some(r) = &s.reference {
            toml_ser::emit_string_kv(&mut out, "reference", r);
        }
        if let Some(t) = &s.tags {
            toml_ser::emit_string_array(&mut out, "tags", t);
        }
    }
    header(&mut out, "default");
    if let Some(i) = &cfg.default.interpreter {
        toml_ser::emit_string_array(&mut out, "interpreter", i);
    }
    if let Some(w) = cfg.default.command_width {
        toml_ser::emit_int_kv(&mut out, "command_width", w as u64);
    }
    out
}

// ---------------------------------------------------------------------------
// Paths

extern "C" {
    fn getuid() -> u32;
    fn getpwuid(uid: u32) -> *const Passwd;
}

#[repr(C)]
struct Passwd {
    pw_name: *const std::os::raw::c_char,
    pw_passwd: *const std::os::raw::c_char,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *const std::os::raw::c_char,
    pw_dir: *const std::os::raw::c_char,
    pw_shell: *const std::os::raw::c_char,
}

fn passwd_home() -> Option<PathBuf> {
    use std::ffi::CStr;
    use std::os::unix::ffi::OsStrExt;
    unsafe {
        let pw = getpwuid(getuid());
        if pw.is_null() {
            return None;
        }
        let dir = (*pw).pw_dir;
        if dir.is_null() {
            return None;
        }
        let bytes = CStr::from_ptr(dir).to_bytes();
        if bytes.is_empty() {
            return None;
        }
        Some(PathBuf::from(std::ffi::OsStr::from_bytes(bytes)))
    }
}

pub fn home_dir() -> Option<PathBuf> {
    match std::env::var_os("HOME") {
        Some(h) if !h.is_empty() => Some(PathBuf::from(h)),
        _ => passwd_home(),
    }
}

pub fn config_dir() -> Option<PathBuf> {
    match std::env::var_os("XDG_CONFIG_HOME") {
        Some(x) if Path::new(&x).is_absolute() => Some(PathBuf::from(x)),
        _ => home_dir().map(|h| h.join(".config")),
    }
}

pub fn find_default_config() -> Option<PathBuf> {
    let mut candidates: Vec<PathBuf> = Vec::new();
    candidates.push(PathBuf::from("pier.toml"));
    if let Some(c) = config_dir() {
        candidates.push(c.join("pier").join("config.toml"));
        candidates.push(c.join("pier").join("config"));
        candidates.push(c.join("pier.toml"));
    }
    if let Some(h) = home_dir() {
        candidates.push(h.join(".pier.toml"));
        candidates.push(h.join(".pier"));
    }
    candidates.into_iter().find(|p| p.exists())
}

pub fn default_init_path() -> PathBuf {
    match config_dir() {
        Some(c) => c.join("pier").join("config.toml"),
        None => PathBuf::from("pier").join("config.toml"),
    }
}
