use crate::width::display_width;

pub struct Table {
    titles: Vec<Vec<String>>,
    rows: Vec<Vec<Vec<String>>>,
}

fn cell(s: &str) -> Vec<String> {
    s.lines().map(|l| l.to_string()).collect()
}

