            titles: titles.iter().map(|t| cell(t)).collect(),
            rows: Vec::new(),
        }
    }

    pub fn add_row(&mut self, cells: Vec<String>) {
        self.rows.push(cells.iter().map(|c| cell(c)).collect());
    }

    pub fn render(&self) -> String {
        let ncols = self
            .rows
            .iter()
            .map(|r| r.len())
            .chain(std::iter::once(self.titles.len()))
            .max()
            .unwrap_or(0);
        let mut widths = vec![0usize; ncols];
        for (j, w) in widths.iter_mut().enumerate() {
            if let Some(c) = self.titles.get(j) {
                *w = (*w).max(cell_width(c));
            }
            for r in &self.rows {
                if let Some(c) = r.get(j) {
                    *w = (*w).max(cell_width(c));
                }
            }
        }
        let mut out = String::new();
        let sep = {
            let mut s = String::new();
            s.push('≖');
            for (j, w) in widths.iter().enumerate() {
                for _ in 0..(w + 2) {
                    s.push('≖');
                }
                if j + 1 < widths.len() {
                    s.push('≖');
                }
            }
            s.push('≖');
            s.push('\n');
            s
        };
        let print_row = |out: &mut String, row: &[Vec<String>]| {
            let height = row.iter().map(|c| c.len()).max().unwrap_or(0);
            for i in 0..height {
                out.push('⋮');
                for (j, w) in widths.iter().enumerate() {
                    out.push(' ');
                    let text = row.get(j).and_then(|c| c.get(i)).map(|s| s.as_str()).unwrap_or("");
                    out.push_str(text);
                    let tw = display_width(text);
                    if tw < *w {
                        for _ in 0..(w - tw) {
                            out.push(' ');
                        }
                    }
                    out.push(' ');
                    if j + 1 < widths.len() {
                        out.push('⋮');
                    }
                }
                out.push('⋮');
                out.push('\n');
            }
        };
        out.push_str(&sep);
        print_row(&mut out, &self.titles);
        out.push_str(&sep);
        for r in &self.rows {
            print_row(&mut out, r);
        }
        out.push_str(&sep);
        out
    }
}
