#[derive(Debug, Clone)]
pub struct Matched {
    pub name: &'static str,
    pub occurs: u64,
    pub vals: Vec<OsString>,
}

#[derive(Debug, Clone, Default)]
pub struct Matcher {
    pub entries: Vec<Matched>,
}

impl Matcher {
    fn get(&self, name: &str) -> Option<&Matched> {
        self.entries.iter().find(|e| e.name == name)
    }
    fn get_mut(&mut self, name: &'static str) -> &mut Matched {
        if let Some(i) = self.entries.iter().position(|e| e.name == name) {
            &mut self.entries[i]
        } else {
            self.entries.push(Matched {
                name,
                occurs: 0,
                vals: Vec::new(),
            });
            self.entries.last_mut().unwrap()
        }
    }
    fn contains(&self, name: &str) -> bool {
        self.get(name).is_some()
    }
    fn inc(&mut self, name: &'static str) {
        self.get_mut(name).occurs += 1;
    }
    fn add_val(&mut self, name: &'static str, v: OsString) {
        self.get_mut(name).vals.push(v);
    }
    fn insert(&mut self, name: &'static str) {
        let _ = self.get_mut(name);
    }

    pub fn is_present(&self, name: &str) -> bool {
        self.contains(name)
    }
    pub fn value_of(&self, name: &str) -> Option<&OsString> {
        self.get(name).and_then(|m| m.vals.first())
    }
    pub fn values_of(&self, name: &str) -> Option<Vec<OsString>> {
        self.get(name).map(|m| m.vals.clone())
    }
}

