cd /workspace/src && cat > cli.rs <<'EOF'
//! A small command line parser that reproduces the behaviour and messages of
//! the argument parser used by the original pier binary.

use crate::help_text;
use crate::textwrap::wrap_help;
use crate::width::str_width;
use std::ffi::OsString;
use std::os::unix::ffi::OsStrExt;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Kind {
    Flag,
    Opt,
    Pos,
}

#[derive(Clone)]
pub struct ArgSpec {
    pub name: &'static str,
    pub disp: &'static str,
    pub kind: Kind,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub multiple: bool,
    pub min_vals_zero: bool,
    pub required: bool,
    pub env: Option<&'static str>,
    pub validator: Option<fn(&str) -> Result<(), String>>,
}

impl ArgSpec {
    fn base(name: &'static str, kind: Kind) -> ArgSpec {
        ArgSpec {
            name,
            disp: name,
            kind,
            short: None,
            long: None,
            multiple: false,
            min_vals_zero: false,
            required: false,
            env: None,
            validator: None,
        }
    }
    pub fn flag(name: &'static str, short: char, long: &'static str) -> ArgSpec {
        let mut a = ArgSpec::base(name, Kind::Flag);
        a.short = Some(short);
        a.long = Some(long);
        a
    }
    pub fn opt(name: &'static str, short: char, long: &'static str) -> ArgSpec {
        let mut a = ArgSpec::base(name, Kind::Opt);
        a.short = Some(short);
        a.long = Some(long);
        a
    }
    pub fn pos(name: &'static str) -> ArgSpec {
        ArgSpec::base(name, Kind::Pos)
    }
    pub fn required(mut self) -> ArgSpec {
        self.required = true;
        self
    }
    pub fn multiple(mut self) -> ArgSpec {
        self.multiple = true;
        self
    }
    pub fn min_zero(mut self) -> ArgSpec {
        self.min_vals_zero = true;
        self
    }
    pub fn env(mut self, e: &'static str) -> ArgSpec {
        self.env = Some(e);
        self
    }
    pub fn validator(mut self, v: fn(&str) -> Result<(), String>) -> ArgSpec {
        self.validator = Some(v);
        self
    }

    fn display(&self) -> String {
        match self.kind {
            Kind::Flag => match self.long {
                Some(l) => format!("--{}", l),
                None => format!("-{}", self.short.unwrap_or('?')),
            },
            Kind::Opt => {
                let mut s = match self.long {
                    Some(l) => format!("--{} ", l),
                    None => format!("-{} ", self.short.unwrap_or('?')),
                };
                s.push_str(&format!("<{}>", self.disp));
                if self.multiple {
                    s.push_str("...");
                }
                s
            }
            Kind::Pos => {
                let mut s = format!("<{}>", self.disp);
                if self.multiple {
                    s.push_str("...");
                }
                s
            }
        }
    }
}

pub struct AppSpec {
    pub name: &'static str,
    pub aliases: Vec<&'static str>,
    pub args: Vec<ArgSpec>,
    pub subcommands: Vec<AppSpec>,
    pub trailing_var_arg: bool,
    pub negate_reqs: bool,
    pub usage: &'static str,
    pub help_short: &'static str,
    pub help_long: Option<&'static str>,
    pub is_help: bool,
}

impl AppSpec {
    pub fn new(name: &'static str, usage: &'static str, help_short: &'static str) -> AppSpec {
        AppSpec {
            name,
            aliases: Vec::new(),
            args: Vec::new(),
            subcommands: Vec::new(),
            trailing_var_arg: false,
            negate_reqs: false,
            usage,
            help_short,
            help_long: None,
            is_help: false,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Matched {
    pub name: &'static str,
    pub occurs: u64,
    pub vals: Vec<OsString>,
}

#[derive(Debug, Clone, Default)]
pub struct Matcher {
    pub entries: Vec<Matched>,
}

impl Matcher {
    fn get(&self, name: &str) -> Option<&Matched> {
        self.entries.iter().find(|e| e.name == name)
    }
    fn get_mut(&mut self, name: &'static str) -> &mut Matched {
        if let Some(i) = self.entries.iter().position(|e| e.name == name) {
            &mut self.entries[i]
        } else {
            self.entries.push(Matched {
                name,
                occurs: 0,
                vals: Vec::new(),
            });
            self.entries.last_mut().unwrap()
        }
    }
    fn contains(&self, name: &str) -> bool {
        self.get(name).is_some()
    }
    fn inc(&mut self, name: &'static str) {
        self.get_mut(name).occurs += 1;
    }
    fn add_val(&mut self, name: &'static str, v: OsString) {
        self.get_mut(name).vals.push(v);
    }
    fn insert(&mut self, name: &'static str) {
        let _ = self.get_mut(name);
    }

    pub fn is_present(&self, name: &str) -> bool {
        self.contains(name)
    }
    pub fn value_of(&self, name: &str) -> Option<&OsString> {
        self.get(name).and_then(|m| m.vals.first())
    }
    pub fn values_of(&self, name: &str) -> Option<Vec<OsString>> {
        self.get(name).map(|m| m.vals.clone())
    }
}

#[derive(Debug)]
pub struct Matches {
    pub args: Matcher,
    pub sub: Option<(&'static str, Box<Matches>)>,
}

pub enum Outcome {
    Stdout(String),
    Stderr(String),
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum PR {
    NotFound,
    Flag,
    Opt(&'static str),
    ValuesDone,
}

pub struct Ctx {
    pub bin: String,
    pub color: bool,
}

impl Ctx {
    fn error(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

fn always_good(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

// ---------------------------------------------------------------------------
// String similarity (Jaro-Winkler)

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let search_range = (a_len.max(b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b_len - 1).min(i + search_range);
        for j in 0..=max_bound {
            if min_bound <= j && *a_elem == b[j] && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|(x, y)| x == y)
        .count();
    let jw = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean<'a, I: IntoIterator<Item = &'a str>>(v: &str, candidates: I) -> Option<&'a str> {
    let mut candidate: Option<(f64, &str)> = None;
    for pv in candidates {
        let confidence = jaro_winkler(v, pv);
        if confidence > 0.8 && (candidate.is_none() || candidate.unwrap().0 < confidence) {
            candidate = Some((confidence, pv));
        }
    }
    candidate.map(|c| c.1)
}

// ---------------------------------------------------------------------------

fn help_flag() -> ArgSpec {
    ArgSpec::flag("hclap_help", 'h', "help")
}

fn version_flag() -> ArgSpec {
    ArgSpec::flag("vclap_version", 'V', "version")
}

struct Parser<'a> {
    app: &'a AppSpec,
    ctx: &'a Ctx,
    bin: String,
    args: Vec<ArgSpec>,
}

fn trim_left(b: &[u8], c: u8) -> &[u8] {
    let mut i = 0;
    while i < b.len() && b[i] == c {
        i += 1;
    }
    &b[i..]
}

fn fill_template(tmpl: &str, subs: &[(&str, &str)]) -> String {
    let mut out = String::with_capacity(tmpl.len() + 64);
    let mut rest = tmpl;
    'outer: while !rest.is_empty() {
        if rest.starts_with('{') {
            for (k, v) in subs {
                if rest.starts_with(k) {
                    out.push_str(v);
                    rest = &rest[k.len()..];
                    continue 'outer;
                }
            }
        }
        let c = rest.chars().next().unwrap();
        out.push(c);
        rest = &rest[c.len_utf8()..];
    }
    out
}

fn env_spec() -> String {
    let val = std::env::var_os("PIER_CONFIG_PATH")
        .map(|v| v.to_string_lossy().into_owned())
        .unwrap_or_default();
    format!(" [env: PIER_CONFIG_PATH={}]", val)
}

fn cfg_short_line() -> String {
    let h = "Sets a custom config file";
    let spec = env_spec();
    let longest = 20usize;
    let spcs = longest + 12;
    let term_w = 120usize;
    let mut help = format!("{}{}", h, spec);
    let too_long = spcs + str_width(h) + str_width(&spec) >= term_w;
    if too_long {
        help = wrap_help(&help, term_w - spcs);
    }
    let mut out = String::from("    -c, --config-file <path>    ");
    let mut lines = help.lines();
    if let Some(first) = lines.next() {
        out.push_str(first);
    }
    for l in lines {
        out.push('\n');
        out.push_str(&" ".repeat(longest + 12));
        out.push_str(l);
    }
    out
}

fn cfg_long_env() -> String {
    let spec = env_spec();
    let wrapped = wrap_help(&spec, 120 - 12);
    let mut parts = Vec::new();
    for l in wrapped.lines() {
        parts.push(format!("            {}", l));
    }
    if parts.is_empty() {
        parts.push("            ".to_string());
    }
    parts.join("\n")
}

pub fn render_help(app: &AppSpec, top_bin: &str, app_bin: &str, use_long: bool) -> String {
    let tmpl = if use_long {
        app.help_long.unwrap_or(app.help_short)
    } else {
        app.help_short
    };
    let hdr = if app_bin.contains(' ') {
        app_bin.replace(' ', "-")
    } else {
        app.name.to_string()
    };
    let mut subs: Vec<(&str, String)> = vec![("{HDR}", hdr), ("{BIN}", top_bin.to_string())];
    if tmpl.contains("{CFG_SHORT}") {
        subs.push(("{CFG_SHORT}", cfg_short_line()));
    }
    if tmpl.contains("{CFG_LONG_ENV}") {
        subs.push(("{CFG_LONG_ENV}", cfg_long_env()));
    }
    let subs_ref: Vec<(&str, &str)> = subs.iter().map(|(k, v)| (*k, v.as_str())).collect();
    fill_template(tmpl, &subs_ref)
}

fn render_version(app: &AppSpec, app_bin: &str) -> String {
    let hdr = if app_bin.contains(' ') {
        app_bin.replace(' ', "-")
    } else {
        app.name.to_string()
    };
    format!("{} 0.1.6\n", hdr)
}

impl<'a> Parser<'a> {
    fn new(app: &'a AppSpec, ctx: &'a Ctx, bin: String) -> Parser<'a> {
        let mut flags: Vec<ArgSpec> = app.args.iter().filter(|a| a.kind == Kind::Flag).cloned().collect();
        if !app.is_help {
            flags.push(help_flag());
            flags.push(version_flag());
        }
        let mut args = flags;
        args.extend(app.args.iter().filter(|a| a.kind == Kind::Opt).cloned());
        args.extend(app.args.iter().filter(|a| a.kind == Kind::Pos).cloned());
        Parser { app, ctx, bin, args }
    }

    fn top_bin(&self) -> &str {
        &self.ctx.bin
    }

    fn arg(&self, name: &str) -> &ArgSpec {
        self.args.iter().find(|a| a.name == name).expect("unknown arg")
    }

    fn positionals(&self) -> Vec<&ArgSpec> {
        self.args.iter().filter(|a| a.kind == Kind::Pos).collect()
    }

    fn required(&self) -> Vec<&'static str> {
        // definition order
        self.app.args.iter().filter(|a| a.required).map(|a| a.name).collect()
    }

    fn help_usage(&self) -> String {
        fill_template(self.app.usage, &[("{BIN}", self.top_bin())])
    }

    fn required_usage_from(&self, reqs: &[&'static str], matcher: Option<&Matcher>) -> Vec<String> {
        let mut desc: Vec<&'static str> = reqs.to_vec();
        desc.sort();
        desc.dedup();
        let mut out = Vec::new();
        for p in self.positionals() {
            if desc.contains(&p.name) && matcher.map_or(true, |m| !m.contains(p.name)) {
                out.push(p.display());
            }
        }
        for name in &desc {
            let a = match self.args.iter().find(|a| a.name == *name) {
                Some(a) => a,
                None => continue,
            };
            if a.kind == Kind::Pos {
                continue;
            }
            if matcher.map_or(false, |m| m.contains(name)) {
                continue;
            }
            out.push(a.display());
        }
        out
    }

    fn smart_usage(&self, used: &[&'static str]) -> String {
        let mut hs: Vec<&'static str> = self.required();
        hs.extend_from_slice(used);
        let r = self.required_usage_from(&hs, None);
        let mut s = self.bin.clone();
        for x in r {
            s.push(' ');
            s.push_str(&x);
        }
        s
    }

    fn error_usage(&self, m: &Matcher, extra: Option<&'static str>) -> String {
        let mut used: Vec<&'static str> = Vec::new();
        for e in &m.entries {
            let a = self.arg(e.name);
            let keep = match a.kind {
                Kind::Opt => !a.required,
                Kind::Pos => false,
                Kind::Flag => true,
            };
            if keep {
                used.push(e.name);
            }
        }
        if let Some(x) = extra {
            used.push(x);
        }
        let body = if used.is_empty() {
            self.help_usage()
        } else {
            self.smart_usage(&used)
        };
        format!("USAGE:\n    {}", body)
    }

    // ---- errors

    fn unknown_argument(&self, arg: &str, suffix: &str, usage: String) -> Outcome {
        let c = self.ctx;
        Outcome::Stderr(format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(arg),
            if suffix.is_empty() {
                "\n".to_string()
            } else {
                format!("{}\n", suffix)
            },
            usage,
            c.good("--help")
        ))
    }

    fn invalid_subcommand(&self, s: &str, dym: &str, usage: String) -> Outcome {
        let c = self.ctx;
        Outcome::Stderr(format!(
            "{} The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} {} {}'\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(s),
            c.good(dym),
            self.bin,
            c.good("--"),
            s,
            usage,
            c.good("--help")
        ))
    }

    fn unrecognized_subcommand(&self, s: &str) -> Outcome {
        let c = self.ctx;
        Outcome::Stderr(format!(
            "{} The subcommand '{}' wasn't recognized\n\n{}\n\t{} help <subcommands>...\n\nFor more information try {}",
            c.error("error:"),
            c.warning(s),
            c.warning("USAGE:"),
            self.bin,
            c.good("--help")
        ))
    }

    fn empty_value(&self, a: &ArgSpec, m: &Matcher) -> Outcome {
        let c = self.ctx;
        Outcome::Stderr(format!(
            "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(&a.display()),
            self.error_usage(m, None),
            c.good("--help")
        ))
    }

    fn multiple_usage(&self, a: &ArgSpec, m: &Matcher) -> Outcome {
        let c = self.ctx;
        Outcome::Stderr(format!(
            "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(&a.display()),
            self.error_usage(m, None),
            c.good("--help")
        ))
    }

    fn value_validation(&self, a: &ArgSpec, err: &str) -> Outcome {
        let c = self.ctx;
        Outcome::Stderr(format!(
            "{} Invalid value for '{}': {}",
            c.error("error:"),
            c.warning(&a.display()),
            err
        ))
    }

    fn missing_required(&self, m: &Matcher) -> Outcome {
        let c = self.ctx;
        let mut reqs: Vec<&'static str> = self.required();
        reqs.retain(|n| !m.contains(n));
        reqs.dedup();
        let list = self.required_usage_from(&reqs, Some(m));
        let mut req_args = String::new();
        for s in list {
            req_args.push_str("\n    ");
            req_args.push_str(&c.error(&s));
        }
        Outcome::Stderr(format!(
            "{} The following required arguments were not provided:{}\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            req_args,
            self.error_usage(m, None),
            c.good("--help")
        ))
    }

    // ---- parsing helpers

    fn find_subcommand(&self, arg: &[u8]) -> Option<&'a AppSpec> {
        let app: &'a AppSpec = self.app;
        for sc in &app.subcommands {
            if sc.name.as_bytes() == arg {
                return Some(sc);
            }
            if sc.aliases.iter().any(|a| a.as_bytes() == arg) {
                return Some(sc);
            }
        }
        None
    }

    fn sc_names(&self) -> Vec<&'static str> {
        let mut v: Vec<&'static str> = self.app.subcommands.iter().map(|s| s.name).collect();
        for s in &self.app.subcommands {
            v.extend(s.aliases.iter().copied());
        }
        v
    }

    fn is_new_arg(&self, arg: &[u8], needs: PR) -> bool {
        if needs == PR::ValuesDone {
            return true;
        }
        if arg.starts_with(b"--") {
            true
        } else if arg.starts_with(b"-") {
            arg.len() != 1
        } else {
            false
        }
    }

    fn needs_more_vals(&self, m: &Matcher, a: &ArgSpec) -> bool {
        if m.contains(a.name) {
            if a.min_vals_zero {
                return true;
            }
            return a.multiple;
        }
        true
    }

    fn add_val(&self, m: &mut Matcher, a: &ArgSpec, v: OsString) -> PR {
        m.add_val(a.name, v);
        if self.needs_more_vals(m, a) {
            PR::Opt(a.name)
        } else {
            PR::ValuesDone
        }
    }

    fn parse_opt(&self, m: &mut Matcher, val: Option<&[u8]>, a: &ArgSpec, had_eq: bool) -> PR {
        let mut has_eq = false;
        let no_val = val.is_none();
        if let Some(fv) = val {
            has_eq = fv.starts_with(b"=") || had_eq;
            let v = trim_left(fv, b'=');
            self.add_val(m, a, OsString::from(std::ffi::OsStr::from_bytes(v)));
        }
        m.inc(a.name);
        if no_val || (a.multiple && !has_eq && self.needs_more_vals(m, a)) {
            PR::Opt(a.name)
        } else {
            PR::ValuesDone
        }
    }

    fn longs(&self) -> Vec<&'static str> {
        let mut v = Vec::new();
        for a in self.args.iter().filter(|a| a.kind == Kind::Flag) {
            if let Some(l) = a.long {
                v.push(l);
            }
        }
        for a in self.args.iter().filter(|a| a.kind == Kind::Opt) {
            if let Some(l) = a.long {
                v.push(l);
            }
        }
        v
    }

    fn parse_long(&self, m: &mut Matcher, full: &[u8], rest: &[OsString]) -> Result<PR, Outcome> {
        let trimmed = trim_left(full, b'-');
        let (name, val) = match trimmed.iter().position(|&b| b == b'=') {
            Some(p) if full.contains(&b'=') => (&trimmed[..p], Some(&trimmed[p..])),
            _ => (trimmed, None),
        };
        if let Some(a) = self
            .args
            .iter()
            .find(|a| a.kind == Kind::Opt && a.long.map(|l| l.as_bytes()) == Some(name))
        {
            let a = a.clone();
            return Ok(self.parse_opt(m, val, &a, val.is_some()));
        }
        if let Some(a) = self
            .args
            .iter()
            .find(|a| a.kind == Kind::Flag && a.long.map(|l| l.as_bytes()) == Some(name))
        {
            if name == b"help" {
                return Err(Outcome::Stdout(render_help(
                    self.app,
                    self.top_bin(),
                    &self.bin,
                    true,
                )));
            }
            if name == b"version" {
                return Err(Outcome::Stdout(render_version(self.app, &self.bin)));
            }
            m.inc(a.name);
            return Ok(PR::Flag);
        }
        let name_s = String::from_utf8_lossy(name).into_owned();
        let rest_s: Vec<String> = rest.iter().map(|r| r.to_string_lossy().into_owned()).collect();
        let mut suffix = String::new();
        if let Some(c) = did_you_mean(&name_s, self.longs()) {
            suffix = format!("\n\tDid you mean {}{}?", always_good("--"), always_good(c));
            if let Some(a) = self.args.iter().find(|a| a.kind != Kind::Pos && a.long == Some(c)) {
                m.insert(a.name);
            }
        } else {
            let mut best: Option<(usize, String)> = None;
            for sc in &self.app.subcommands {
                let mut cands: Vec<&'static str> = Vec::new();
                for a in sc.args.iter().filter(|a| a.kind == Kind::Flag) {
                    if let Some(l) = a.long {
                        cands.push(l);
                    }
                }
                for a in sc.args.iter().filter(|a| a.kind == Kind::Opt) {
                    if let Some(l) = a.long {
                        cands.push(l);
                    }
                }
                let cand = match did_you_mean(&name_s, cands) {
                    Some(c) => c,
                    None => continue,
                };
                let score = match rest_s.iter().position(|x| x == sc.name) {
                    Some(s) => s,
                    None => continue,
                };
                let sfx = format!(
                    "\n\tDid you mean to put '{}{}' after the subcommand '{}'?",
                    always_good("--"),
                    always_good(cand),
                    always_good(sc.name)
                );
                if best.as_ref().map_or(true, |(b, _)| score < *b) {
                    best = Some((score, sfx));
                }
            }
            if let Some((_, s)) = best {
                suffix = s;
            }
        }
        let used = format!("--{}", name_s);
        Err(self.unknown_argument(&used, &suffix, self.error_usage(m, None)))
    }

    fn parse_short(&self, m: &mut Matcher, full: &[u8]) -> Result<PR, Outcome> {
        let arg_os = trim_left(full, b'-');
        let arg = String::from_utf8_lossy(arg_os).into_owned();
        let mut ret = PR::NotFound;
        for c in arg.chars() {
            if let Some(a) = self
                .args
                .iter()
                .find(|a| a.kind == Kind::Opt && a.short == Some(c))
            {
                let a = a.clone();
                let p0_len = arg.find(c).unwrap_or(0);
                let i = p0_len + c.len_utf8();
                let val = if i < arg.len() {
                    if i <= arg_os.len() {
                        Some(&arg_os[i..])
                    } else {
                        None
                    }
                } else {
                    None
                };
                return Ok(self.parse_opt(m, val, &a, false));
            } else if let Some(a) = self
                .args
                .iter()
                .find(|a| a.kind == Kind::Flag && a.short == Some(c))
            {
                if c == 'h' && a.name == "hclap_help" {
                    return Err(Outcome::Stdout(render_help(
                        self.app,
                        self.top_bin(),
                        &self.bin,
                        false,
                    )));
                }
                if c == 'V' && a.name == "vclap_version" {
                    return Err(Outcome::Stdout(render_version(self.app, &self.bin)));
                }
                m.inc(a.name);
                ret = PR::Flag;
            } else {
                let s = format!("-{}", c);
                return Err(self.unknown_argument(&s, "", self.error_usage(m, None)));
            }
        }
        Ok(ret)
    }

    fn parse_help_subcommand(&self, cmds: &[OsString]) -> Outcome {
        let mut help_help = false;
        let mut bin_name = self.bin.clone();
        let mut sc: &AppSpec = self.app;
        let mut is_self = true;
        for (i, cmd) in cmds.iter().enumerate() {
            let c = cmd.to_string_lossy();
            if c == "help" {
                help_help = true;
            }
            let found = sc
                .subcommands
                .iter()
                .find(|s| s.name == c)
                .or_else(|| sc.subcommands.iter().find(|s| s.aliases.iter().any(|a| *a == c)));
            match found {
                Some(s) => {
                    sc = s;
                    is_self = false;
                    if i == cmds.len() - 1 {
                        break;
                    }
                }
                None => {
                    return self.unrecognized_subcommand(&c);
                }
            }
            bin_name = format!("{} {}", bin_name, sc.name);
        }
        let _ = help_help;
        let sc_bin = if is_self {
            self.bin.clone()
        } else {
            format!("{} {}", bin_name, sc.name)
        };
        Outcome::Stdout(render_help(sc, self.top_bin(), &sc_bin, false))
    }

    // ---- main loop

    fn get_matches(&self, args: &[OsString]) -> Result<Matches, Outcome> {
        let mut m = Matcher::default();
        let mut needs = PR::NotFound;
        let mut pos_counter = 1usize;
        let mut trailing = false;
        let mut sub: Option<&'a AppSpec> = None;
        let positionals: Vec<ArgSpec> = self.positionals().into_iter().cloned().collect();
        let mut i = 0usize;
        while i < args.len() {
            let arg = &args[i];
            i += 1;
            let bytes = arg.as_bytes();
            let starts_new = self.is_new_arg(bytes, needs);
            if !trailing && bytes == b"--" && starts_new {
                trailing = true;
                continue;
            }
            if !trailing {
                if !matches!(needs, PR::Opt(_)) {
                    if let Some(sc) = self.find_subcommand(bytes) {
                        if sc.is_help {
                            return Err(self.parse_help_subcommand(&args[i..]));
                        }
                        sub = Some(sc);
                        break;
                    }
                }
                if starts_new {
                    if bytes.starts_with(b"--") {
                        needs = self.parse_long(&mut m, bytes, &args[i..])?;
                        continue;
                    } else if bytes.starts_with(b"-") && bytes.len() != 1 {
                        needs = self.parse_short(&mut m, bytes)?;
                        continue;
                    }
                } else if let PR::Opt(name) = needs {
                    let a = self.arg(name).clone();
                    needs = self.add_val(&mut m, &a, arg.clone());
                    continue;
                }
            }
            let lossy = arg.to_string_lossy().into_owned();
            if !self.app.subcommands.is_empty() {
                let names = self.sc_names();
                if let Some(c) = did_you_mean(&lossy, names.iter().copied()) {
                    return Err(self.invalid_subcommand(&lossy, c, self.error_usage(&m, None)));
                }
            }
            if let Some(p) = positionals.get(pos_counter - 1) {
                if !trailing && self.app.trailing_var_arg && pos_counter == positionals.len() {
                    trailing = true;
                }
                m.add_val(p.name, arg.clone());
                m.inc(p.name);
                if !p.multiple {
                    pos_counter += 1;
                }
            } else {
                return Err(self.unknown_argument(&lossy, "", self.error_usage(&m, None)));
            }
        }

        let mut sub_matches = None;
        if let Some(sc) = sub {
            let sc_bin = format!("{} {}", self.bin, sc.name);
            let p = Parser::new(sc, self.ctx, sc_bin);
            let sm = p.get_matches(&args[i..])?;
            sub_matches = Some((sc.name, Box::new(sm)));
        }

        self.validate(needs, sub.is_some(), &mut m)?;
        Ok(Matches {
            args: m,
            sub: sub_matches,
        })
    }

    fn validate_required(&self, m: &Matcher) -> Result<(), Outcome> {
        for name in self.required() {
            if !m.contains(name) {
                return Err(self.missing_required(m));
            }
        }
        Ok(())
    }

    fn validate(&self, needs: PR, has_sub: bool, m: &mut Matcher) -> Result<(), Outcome> {
        // environment values
        let env_args: Vec<ArgSpec> = self
            .args
            .iter()
            .filter(|a| a.kind == Kind::Opt && a.env.is_some())
            .cloned()
            .collect();
        for a in &env_args {
            if let Some(v) = std::env::var_os(a.env.unwrap()) {
                self.add_val(m, a, v);
            }
        }
        let mut reqs_validated = false;
        if let PR::Opt(name) = needs {
            self.validate_required(m)?;
            reqs_validated = true;
            let a = self.arg(name);
            let should_err = match m.get(name) {
                Some(ma) => ma.vals.is_empty() && !a.min_vals_zero,
                None => true,
            };
            if should_err {
                return Err(self.empty_value(a, m));
            }
        }
        if !(self.app.negate_reqs && has_sub) && !reqs_validated {
            self.validate_required(m)?;
        }
        // matched args
        for e in m.entries.clone() {
            let a = self.arg(e.name);
            match a.kind {
                Kind::Opt => {
                    if !a.min_vals_zero && e.vals.is_empty() {
                        return Err(self.empty_value(a, m));
                    }
                    if let Some(v) = a.validator {
                        for val in &e.vals {
                            if let Err(err) = v(&val.to_string_lossy()) {
                                return Err(self.value_validation(a, &err));
                            }
                        }
                    }
                    if e.occurs > 1 && !a.multiple {
                        return Err(self.multiple_usage(a, m));
                    }
                }
                Kind::Flag => {
                    if e.occurs > 1 && !a.multiple {
                        return Err(self.multiple_usage(a, m));
                    }
                }
                Kind::Pos => {
                    if e.occurs > 1 && !a.multiple {
                        return Err(self.multiple_usage(a, m));
                    }
                }
            }
        }
        Ok(())
    }
}

pub fn parse(app: &AppSpec, ctx: &Ctx, args: &[OsString]) -> Result<Matches, Outcome> {
    let p = Parser::new(app, ctx, ctx.bin.clone());
    p.get_matches(args)
}

// ---------------------------------------------------------------------------
// The pier command line definition

fn usize_validator(s: &str) -> Result<(), String> {
    s.parse::<usize>().map(|_| ()).map_err(|e| e.to_string())
}

pub fn build_app() -> AppSpec {
    let mut top = AppSpec::new(
        "pier",
        "{BIN} [FLAGS] [OPTIONS] <alias> [args]...\n    {BIN} [FLAGS] [OPTIONS] <SUBCOMMAND>",
        help_text::TOP_SHORT,
    );
    top.help_long = Some(help_text::TOP_LONG);
    top.trailing_var_arg = true;
    top.negate_reqs = true;
    let mut path = ArgSpec::opt("path", 'c', "config-file").env("PIER_CONFIG_PATH");
    path.disp = "path";
    top.args = vec![
        path,
        ArgSpec::flag("verbose", 'v', "verbose"),
        ArgSpec::pos("alias").required(),
        ArgSpec::pos("args").multiple(),
    ];

    let mut add = AppSpec::new(
        "add",
        "{BIN} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]",
        help_text::ADD,
    );
    add.args = vec![
        ArgSpec::pos("command"),
        ArgSpec::opt("alias", 'a', "alias").required(),
        ArgSpec::opt("description", 'd', "description"),
        ArgSpec::opt("tags", 't', "tag").multiple().min_zero(),
        ArgSpec::flag("force", 'f', "force"),
    ];

    let mut init = AppSpec::new("config-init", "{BIN} config-init", help_text::CONFIG_INIT);
    init.aliases = vec!["init"];

    let mut copy = AppSpec::new("copy", "{BIN} copy <from-alias> <to-alias>", help_text::COPY);
    copy.aliases = vec!["cp"];
    copy.args = vec![
        ArgSpec::pos("from-alias").required(),
        ArgSpec::pos("to-alias").required(),
    ];

    let mut edit = AppSpec::new("edit", "{BIN} edit <alias>", help_text::EDIT);
    edit.args = vec![ArgSpec::pos("alias").required()];

    let mut list = AppSpec::new("list", "{BIN} list [FLAGS] [OPTIONS]", help_text::LIST_SHORT);
    list.help_long = Some(help_text::LIST_LONG);
    list.aliases = vec!["ls"];
    list.args = vec![
        ArgSpec::flag("list-aliases", 'q', "list_aliases"),
        ArgSpec::flag("cmd-full", 'l', "cmd_full"),
        ArgSpec::opt("cmd-width", 'c', "cmd_width").validator(usize_validator),
        ArgSpec::opt("tags", 't', "tag").multiple().min_zero(),
    ];

    let mut mv = AppSpec::new(
        "move",
        "{BIN} move [FLAGS] <from-alias> <to-alias>",
        help_text::MOVE,
    );
    mv.aliases = vec!["mv", "rename"];
    mv.args = vec![
        ArgSpec::pos("from-alias").required(),
        ArgSpec::pos("to-alias").required(),
        ArgSpec::flag("force", 'f', "force"),
    ];

    let mut rm = AppSpec::new("remove", "{BIN} remove <alias>", help_text::REMOVE);
    rm.aliases = vec!["rm"];
    rm.args = vec![ArgSpec::pos("alias").required()];

    let mut run = AppSpec::new("run", "{BIN} run <alias> [args]...", help_text::RUN);
    run.args = vec![ArgSpec::pos("alias").required(), ArgSpec::pos("args").multiple()];

    let mut show = AppSpec::new("show", "{BIN} show <alias>", help_text::SHOW);
    show.args = vec![ArgSpec::pos("alias").required()];

    let mut help = AppSpec::new("help", "{BIN} help [subcommand]...", help_text::HELP_HELP);
    help.is_help = true;

    top.subcommands = vec![add, init, copy, edit, list, mv, rm, run, show, help];
    top
}
