fn random_suffix(n: usize) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut seed: u64 = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0x1234_5678);
    seed ^= (std::process::id() as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15);
    let addr = &seed as *const u64 as u64;
    seed ^= addr.rotate_left(17);
    let mut out = String::with_capacity(n);
    for _ in 0..n {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        out.push(CHARS[(seed % CHARS.len() as u64) as usize] as char);
    }
    out
}

fn make_tempdir() -> Result<PathBuf, String> {
    let base = std::env::temp_dir();
    let mut last_err = None;
    for _ in 0..64 {
        let path = base.join(format!("pier{}", random_suffix(6)));
        match std::fs::create_dir(&path) {
            Ok(()) => return Ok(path),
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                last_err = Some(format!("{} at path {:?}", e, path));
                continue;
            }
            Err(e) => return Err(format!("{} at path {:?}", e, path)),
        }
    }
    Err(last_err.unwrap_or_else(|| "too many temporary files exist".to_string()))
}

pub fn panic_exit(location: &str, msg: &str) -> ! {
    use std::io::Write as _;
    let _ = std::io::stdout().flush();
    let mut err = std::io::stderr();
    let _ = write!(
        err,
        "\nthread 'main' panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        location, msg
    );
    std::process::exit(101);
}

pub fn run(
    cfg: &Config,
    script: &Script,
    alias: &str,
    args: &[OsString],
    verbose: bool,
) -> Result<i32, String> {
    if verbose {
        println!("Starting script \"{}\"", alias);
        println!("-------------------------");
    }
    let output = if script.command.starts_with("#!") {
        let dir = make_tempdir()
            .map_err(|e| format!("Failed when trying to create executable tempfile. {}", e))?;
        let path: PathBuf = Path::new(&dir).join(alias);
        let created = (|| -> std::io::Result<()> {
            let mut f = std::fs::OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .mode(0o500)
                .open(&path)?;
            f.write_all(script.command.as_bytes())?;
            f.flush()?;
            Ok(())
        })();
        if let Err(e) = created {
            let _ = std::fs::remove_dir_all(&dir);
            return Err(format!(
                "Failed when trying to create executable tempfile. {}",
                e
            ));
        }
        let res = Command::new(&path)
            .args(args)
            .stdin(Stdio::inherit())
            .stdout(Stdio::inherit())
            .stderr(Stdio::piped())
            .spawn()
            .and_then(|c| c.wait_with_output());
        let _ = std::fs::remove_dir_all(&dir);
        res.map_err(|e| format!("Command execution failed with: {}", e))?
    } else {
        let interp: Vec<String> = match &cfg.default.interpreter {
            Some(i) => i.clone(),
            None => vec![
                std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".to_string()),
                "-c".to_string(),
            ],
        };
        if interp.is_empty() {
            panic_exit(
                "src/script.rs:52:44",
                "index out of bounds: the len is 0 but the index is 0",
            );
        }
        Command::new(&interp[0])
            .args(&interp[1..])
            .arg(&script.command)
            .arg(alias)
            .args(args)
            .stdin(Stdio::inherit())
            .stdout(Stdio::inherit())
            .stderr(Stdio::piped())
            .spawn()
            .and_then(|c| c.wait_with_output())
            .map_err(|e| format!("Command execution failed with: {}", e))?
    };
    if verbose {
        println!("-------------------------");
        println!("Script complete");
    }
    if !output.stderr.is_empty() {
        eprintln!("{}", String::from_utf8_lossy(&output.stderr));
    }
    Ok(output.status.code().unwrap_or(0))
}
