//! Opening the user's editor to capture text.

use std::io::Write;
use std::process::Command;

pub fn edit(initial: &str) -> Result<String, String> {
    let editor = std::env::var("VISUAL")
        .or_else(|_| std::env::var("EDITOR"))
        .unwrap_or_else(|_| "vi".to_string());
    let path = std::env::temp_dir().join(format!("xvrqt_scrawl_{}_{}", std::process::id(), 0));
    let create_err = "Could not create a temporary file to serve as a buffer for the editor.".to_string();
    {
        let mut f = std::fs::File::create(&path).map_err(|_| create_err.clone())?;
        f.write_all(initial.as_bytes()).map_err(|_| create_err.clone())?;
    }
    let status = Command::new(&editor).arg(&path).status();
    match status {
        Ok(s) if s.success() => {}
        _ => {
            return Err(format!(
                "Failed to open `{}` as a text editor or editor was terminated with errors.",
                editor
            ))
        }
    }
    std::fs::read_to_string(&path)
        .map_err(|_| "Failed to capture input. Was not a valid UTF-8 String.".to_string())
}
