fn slice_panic(s: &str, index: usize) -> ! {
    const MAX: usize = 256;
    let mut trunc_len = MAX.min(s.len());
    while !s.is_char_boundary(trunc_len) {
        trunc_len -= 1;
    }
    let s_trunc = &s[..trunc_len];
    let ellipsis = if trunc_len < s.len() { "[...]" } else { "" };
    let mut char_start = index;
    while !s.is_char_boundary(char_start) {
        char_start -= 1;
    }
    let ch = s[char_start..].chars().next().unwrap();
    let msg = format!(
        "byte index {} is not a char boundary; it is inside {:?} (bytes {:?}) of `{}`{}",
        index,
        ch,
        char_start..char_start + ch.len_utf8(),
        s_trunc,
        ellipsis
    );
    runner::panic_exit("src/script.rs:36:52", &msg);
}

fn display_command(s: &Script, full: bool, width: usize) -> String {
    if s.command.starts_with("#!") {
        return "#! script".to_string();
    }
    if full {
        return s.command.clone();
    }
    let first = s.command.lines().next().unwrap_or("");
    if first.chars().count() > width {
        if !first.is_char_boundary(width) {
            slice_panic(first, width);
        }
        first[..width].to_string()
    } else {
        first.to_string()
    }
}

fn cmd_list(path: Option<PathBuf>, m: &Matches) -> Result<i32, String> {
