    if cfg.scripts.is_empty() {
        return Err(no_scripts());
    }
    let a = &m.args;
    let list_aliases = a.is_present("list-aliases");
    let cmd_full = a.is_present("cmd-full");
    let cli_width: Option<usize> = a
        .value_of("cmd-width")
        .and_then(|v| v.to_string_lossy().parse::<usize>().ok());
    let tags: Option<Vec<String>> = if a.is_present("tags") {
        Some(
            a.values_of("tags")
                .unwrap_or_default()
                .iter()
                .map(lossy)
                .collect(),
        )
    } else {
        None
    };
    let mut selected: Vec<(&String, &Script)> = Vec::new();
    match &tags {
        Some(filter) => {
            for (alias, s) in &cfg.scripts {
                for t in filter {
                    if let Some(st) = &s.tags {
                        if st.contains(t) {
                            selected.push((alias, s));
                        }
                    }
                }
            }
        }
        None => {
            for (alias, s) in &cfg.scripts {
                selected.push((alias, s));
            }
        }
    }
    if list_aliases {
        let mut out = String::new();
        for (alias, _) in &selected {
            out.push_str(alias);
            out.push('\n');
        }
        print!("{}", out);
        return Ok(0);
    }
    let width = cli_width.or(cfg.default.command_width).unwrap_or(80);
    let mut t = table::Table::new(&["Alias", "Tags", "Command", "Description"]);
    for (alias, s) in &selected {
        let tags = s.tags.as_ref().map(|t| t.join(",")).unwrap_or_default();
        let cmd = display_command(s, cmd_full, width);
        let desc = s.description.clone().unwrap_or_default();
        t.add_row(vec![alias.to_string(), tags, cmd, desc]);
    }
    print!("{}", t.render());
    Ok(0)
}

