                        .ok_or_else(|| not_found(&from))?;
                    cfg.scripts.insert(to.clone(), s);
                    println!("Copy from alias {} to new alias {}", from, to);
                    save(&cfg, &p)?;
                    Ok(0)
                }
                "move" => {
                    let (mut cfg, p) = load(path)?;
                    let from = a.value_of("from-alias").map(lossy).unwrap_or_default();
                    let to = a.value_of("to-alias").map(lossy).unwrap_or_default();
                    let force = a.is_present("force");
                    if !force && cfg.scripts.contains_key(&to) {
                        return Err(already_exists(&to));
                    }
                    let s = cfg.scripts.remove(&from).ok_or_else(|| not_found(&from))?;
                    cfg.scripts.insert(to.clone(), s);
                    println!("Move from alias {} to new alias {}", from, to);
                    save(&cfg, &p)?;
                    Ok(0)
                }
                "edit" => {
                    let (mut cfg, p) = load(path)?;
                    let alias = a.value_of("alias").map(lossy).unwrap_or_default();
                    let current = fetch(&cfg, &alias)?.command.clone();
                    let new = editor::edit(&current).map_err(editor_err)?;
                    if let Some(s) = cfg.scripts.get_mut(&alias) {
                        s.command = new;
                    }
                    println!("Edited {}", alias);
                    save(&cfg, &p)?;
                    Ok(0)
                }
                "remove" => {
                    let (mut cfg, p) = load(path)?;
                    let alias = a.value_of("alias").map(lossy).unwrap_or_default();
                    if cfg.scripts.is_empty() {
                        return Err(no_scripts());
                    }
                    cfg.scripts.remove(&alias).ok_or_else(|| not_found(&alias))?;
                    println!("Removed {}", alias);
                    save(&cfg, &p)?;
                    Ok(0)
                }
                "show" => {
                    let (cfg, _) = load(path)?;
                    let alias = a.value_of("alias").map(lossy).unwrap_or_default();
                    let s = fetch(&cfg, &alias)?;
                    println!("{}", s.command);
                    Ok(0)
                }
                "run" => {
                    let alias = a.value_of("alias").map(lossy).unwrap_or_default();
                    let args = a.values_of("args").unwrap_or_default();
                    run_alias(path, &alias, &args, verbose)
                }
                "list" => cmd_list(path, sm),
                _ => Ok(0),
            }
        }
    }
}

fn main() {
    match real_main() {
        Ok(code) => exit_with(code),
        Err(e) => {
            let _ = std::io::stdout().flush();
            eprintln!("error: {}", e);
            exit_with(1);
        }
    }
}
