enum ParseErr {
    Io,
    Bad,
}

const NUM_NAMES: usize = 39;
const NUM_STRINGS: usize = 414;
const NUM_BOOLS: usize = 44;

fn parse(data: &[u8]) -> Result<TermInfo, ParseErr> {
    let mut pos = 0usize;
    let rd16 = |pos: &mut usize| -> Result<u16, ParseErr> {
        if *pos + 2 > data.len() {
            return Err(ParseErr::Io);
        }
        let v = u16::from_le_bytes([data[*pos], data[*pos + 1]]);
        *pos += 2;
        Ok(v)
    };
    let magic = rd16(&mut pos)?;
    let wide = match magic {
        0x011A => false,
        0x021E => true,
        _ => return Err(ParseErr::Bad),
    };
    let mut hdr = [0usize; 5];
    for h in hdr.iter_mut() {
        let v = rd16(&mut pos)? as i16;
        *h = if v >= 0 {
            v as usize
        } else if v == -1 {
            0
        } else {
            return Err(ParseErr::Bad);
        };
    }
    let [names_bytes, bools_bytes, numbers_count, string_offsets_count, string_table_bytes] = hdr;
    if names_bytes == 0 || bools_bytes > NUM_BOOLS || numbers_count > NUM_NAMES || string_offsets_count > NUM_STRINGS {
        return Err(ParseErr::Bad);
    }
    if pos + names_bytes > data.len() {
        return Err(ParseErr::Io);
    }
    if std::str::from_utf8(&data[pos..pos + names_bytes - 1]).is_err() {
        return Err(ParseErr::Bad);
    }
    if data[pos + names_bytes - 1] != 0 {
        return Err(ParseErr::Bad);
    }
    pos += names_bytes;
    if pos + bools_bytes > data.len() {
        return Err(ParseErr::Io);
    }
    pos += bools_bytes;
    if (bools_bytes + names_bytes) % 2 == 1 {
        if pos + 1 > data.len() {
            return Err(ParseErr::Io);
        }
        pos += 1;
    }
    let mut numbers = HashMap::new();
    for i in 0..numbers_count {
        let v: u32 = if wide {
            if pos + 4 > data.len() {
                return Err(ParseErr::Io);
            }
            let v = u32::from_le_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]);
            pos += 4;
            v
        } else {
            rd16(&mut pos)? as u32
        };
        if v != 0xFFFF && i == 13 {
            numbers.insert("colors", v);
        }
    }
    let mut strings = HashMap::new();
    if string_offsets_count > 0 {
        let mut offsets = Vec::with_capacity(string_offsets_count);
        for _ in 0..string_offsets_count {
            offsets.push(rd16(&mut pos)?);
        }
        let end = (pos + string_table_bytes).min(data.len());
        let table = &data[pos..end];
        let wanted: &[(usize, &'static str)] =
            &[(39, "sgr0"), (131, "sgr"), (297, "op"), (359, "setaf"), (360, "setab")];
        for (i, &off) in offsets.iter().enumerate() {
            if off == 0xFFFF {
                continue;
            }
            let name = match wanted.iter().find(|(idx, _)| *idx == i) {
                Some((_, n)) => *n,
                None => {
                    // still validate like the reference implementation
                    if off == 0xFFFE {
                        continue;
                    }
                    let off = off as usize;
                    if off > table.len() || !table[off..].contains(&0) {
                        return Err(ParseErr::Bad);
                    }
                    continue;
                }
            };
            if off == 0xFFFE {
                strings.insert(name, Vec::new());
                continue;
            }
            let off = off as usize;
            if off > table.len() {
                return Err(ParseErr::Bad);
            }
            match table[off..].iter().position(|&b| b == 0) {
                Some(len) => {
                    strings.insert(name, table[off..off + len].to_vec());
                }
                None => return Err(ParseErr::Bad),
            }
        }
    }
    Ok(TermInfo { numbers, strings })
}

pub fn from_env() -> Option<TermInfo> {
    let name = match std::env::var("TERM") {
        Ok(t) => t,
        Err(_) => match std::env::var("MSYSCON") {
            Ok(s) if s == "mintty.exe" => "msyscon".to_string(),
            _ => return None,
        },
    };
    if let Some(path) = dbpath_for_term(&name) {
        match std::fs::read(&path) {
            Ok(data) => match parse(&data) {
                Ok(ti) => return Some(ti),
                Err(ParseErr::Io) => {}
                Err(ParseErr::Bad) => return None,
            },
            Err(_) => {}
        }
    }
    if FALLBACK_PREFIXES.iter().any(|p| name.starts_with(p)) {
        return Some(fallback());
    }
    None
}

// ---------------------------------------------------------------------------
// Parameterized string expansion

#[derive(Clone)]
enum Param {
    Num(i32),
    Str(Vec<u8>),
}

pub fn expand(cap: &[u8], params: &[i32]) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    let mut stack: Vec<Param> = Vec::new();
    let mut mparams: Vec<Param> = (0..9)
        .map(|i| Param::Num(*params.get(i).unwrap_or(&0)))
        .collect();
    let mut dyn_vars: Vec<Param> = vec![Param::Num(0); 26];
    let mut static_vars: Vec<Param> = vec![Param::Num(0); 26];
    let pop_num = |stack: &mut Vec<Param>| -> Option<i32> {
        match stack.pop()? {
            Param::Num(n) => Some(n),
            Param::Str(_) => None,
        }
    };
    let mut i = 0usize;
    // skipping state for conditionals
    while i < cap.len() {
        let c = cap[i];
        i += 1;
        if c != b'%' {
            out.push(c);
            continue;
        }
        if i >= cap.len() {
            return None;
        }
        let c = cap[i];
        i += 1;
        match c {
            b'%' => out.push(b'%'),
            b'c' => {
                let n = pop_num(&mut stack)?;
                out.push(n as u8);
            }
            b'd' | b'o' | b'x' | b'X' => {
                let n = pop_num(&mut stack)?;
                let s = match c {
                    b'd' => format!("{}", n),
                    b'o' => format!("{:o}", n),
                    b'x' => format!("{:x}", n),
                    _ => format!("{:X}", n),
                };
                out.extend_from_slice(s.as_bytes());
            }
            b's' => match stack.pop()? {
                Param::Str(s) => out.extend_from_slice(&s),
                Param::Num(_) => return None,
            },
            b'p' => {
                if i >= cap.len() {
                    return None;
                }
                let d = cap[i];
                i += 1;
                if !(b'1'..=b'9').contains(&d) {
                    return None;
                }
                stack.push(mparams[(d - b'1') as usize].clone());
            }
            b'P' | b'g' => {
                if i >= cap.len() {
                    return None;
                }
                let v = cap[i];
                i += 1;
                let slot = if v.is_ascii_uppercase() {
                    Some((true, (v - b'A') as usize))
                } else if v.is_ascii_lowercase() {
                    Some((false, (v - b'a') as usize))
                } else {
                    None
                }?;
                if c == b'P' {
                    let val = stack.pop()?;
                    if slot.0 {
                        static_vars[slot.1] = val;
                    } else {
                        dyn_vars[slot.1] = val;
                    }
                } else if slot.0 {
                    stack.push(static_vars[slot.1].clone());
                } else {
                    stack.push(dyn_vars[slot.1].clone());
                }
            }
            b'\'' => {
                if i + 1 >= cap.len() || cap[i + 1] != b'\'' {
                    return None;
                }
                stack.push(Param::Num(cap[i] as i32));
                i += 2;
            }
            b'{' => {
                let mut n: i32 = 0;
                while i < cap.len() && cap[i].is_ascii_digit() {
                    n = n.wrapping_mul(10).wrapping_add((cap[i] - b'0') as i32);
                    i += 1;
                }
                if i >= cap.len() || cap[i] != b'}' {
                    return None;
                }
                i += 1;
                stack.push(Param::Num(n));
            }
            b'l' => match stack.pop()? {
                Param::Str(s) => stack.push(Param::Num(s.len() as i32)),
                Param::Num(_) => return None,
            },
            b'+' | b'-' | b'*' | b'/' | b'm' | b'&' | b'|' | b'^' | b'=' | b'>' | b'<' | b'A'
            | b'O' => {
                let b2 = pop_num(&mut stack)?;
                let a2 = pop_num(&mut stack)?;
                let r = match c {
                    b'+' => a2.wrapping_add(b2),
                    b'-' => a2.wrapping_sub(b2),
                    b'*' => a2.wrapping_mul(b2),
                    b'/' => {
                        if b2 == 0 {
                            return None;
                        }
                        a2 / b2
                    }
                    b'm' => {
                        if b2 == 0 {
                            return None;
                        }
                        a2 % b2
                    }
                    b'&' => a2 & b2,
                    b'|' => a2 | b2,
                    b'^' => a2 ^ b2,
                    b'=' => (a2 == b2) as i32,
                    b'>' => (a2 > b2) as i32,
                    b'<' => (a2 < b2) as i32,
                    b'A' => (a2 != 0 && b2 != 0) as i32,
                    _ => (a2 != 0 || b2 != 0) as i32,
                };
                stack.push(Param::Num(r));
            }
            b'!' | b'~' => {
                let a2 = pop_num(&mut stack)?;
                stack.push(Param::Num(if c == b'!' { (a2 == 0) as i32 } else { !a2 }));
            }
            b'i' => {
                if let Param::Num(n) = mparams[0] {
                    mparams[0] = Param::Num(n + 1);
                }
                if let Param::Num(n) = mparams[1] {
                    mparams[1] = Param::Num(n + 1);
                }
            }
            b'?' => {}
            b't' => {
                let v = pop_num(&mut stack)?;
                if v == 0 {
                    // skip to matching %e or %;
                    let mut level = 0;
                    loop {
                        if i >= cap.len() {
                            return Some(out);
                        }
                        if cap[i] == b'%' && i + 1 < cap.len() {
                            let d = cap[i + 1];
                            i += 2;
                            match d {
                                b'?' => level += 1,
                                b';' => {
                                    if level == 0 {
                                        break;
                                    }
                                    level -= 1;
                                }
                                b'e' => {
                                    if level == 0 {
                                        break;
                                    }
                                }
                                _ => {}
                            }
                        } else {
                            i += 1;
                        }
                    }
                }
            }
            b'e' => {
                // skip to matching %;
                let mut level = 0;
                loop {
                    if i >= cap.len() {
                        return Some(out);
                    }
                    if cap[i] == b'%' && i + 1 < cap.len() {
                        let d = cap[i + 1];
                        i += 2;
                        match d {
                            b'?' => level += 1,
                            b';' => {
                                if level == 0 {
                                    break;
                                }
                                level -= 1;
                            }
                            _ => {}
                        }
                    } else {
                        i += 1;
                    }
                }
            }
            b';' => {}
            _ => return None,
        }
    }
    Some(out)
}

impl TermInfo {
    fn num_colors(&self) -> u32 {
        if self.strings.contains_key("setaf") && self.strings.contains_key("setab") {
            *self.numbers.get("colors").unwrap_or(&0)
        } else {
            0
        }
    }

    /// Escape sequence for setting the foreground colour (empty if unsupported).
    pub fn fg(&self, color: u32) -> Result<Vec<u8>, ()> {
        let nc = self.num_colors();
        let color = if color >= nc && (8..16).contains(&color) {
            color - 8
        } else {
            color
        };
        if nc > color {
            match self.strings.get("setaf") {
                Some(cap) => expand(cap, &[color as i32]).ok_or(()),
                None => Ok(Vec::new()),
            }
        } else {
            Ok(Vec::new())
        }
    }

    pub fn reset(&self) -> Result<Vec<u8>, ()> {
        for cap in ["sgr0", "sgr", "op"] {
            if let Some(c) = self.strings.get(cap) {
                return expand(c, &[]).ok_or(());
            }
        }
        Ok(Vec::new())
    }
}
